const app=document.querySelector('#app');let data=null,me=null;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opts={}){const res=await fetch('/api'+path,{credentials:'same-origin',headers:{'content-type':'application/json'},...opts});const val=await res.json();if(!res.ok)throw Error((val.error||'تعذر تنفيذ الطلب')+(val.stage?' ('+val.stage+(val.code?' / '+val.code:'')+')':''));return val}
const post=(p,b)=>api(p,{method:'POST',body:JSON.stringify(b)});
const services=[["إكس الصالية","شبكة التواصل الاجتماعي للمملكة","𝕏","x"],["الهوية والإقامة والجوازات","طلبات الإصدار والاعتماد والتحقق والتعاميم","🪪","registry"],["الأحوال المدنية","تسجيل طلبات المواطنين","♧","civil"],["الجوال والاتصالات","خدمات الهاتف والشرائح الرقمية","📱","telecom"],["أبشر الصالية","المركبات والخدمات الوطنية وطلبات التسجيل","🛡️","absher"],["الخدمات البنكية","الحسابات والتحويلات","🏦","banking"],["البطاقات والصرافات","البطاقات وأجهزة الصرف","💳","cards-atm"],["نقاط البيع","عمليات الدفع لدى المتاجر","▣","pos"],["التقسيط","تابي وتمارا الصالية","◈","installments"],["المنافذ الحدودية","فحص الوثائق وحركة الدخول والخروج","✈️","borders"],["الطلبات الحكومية","تقديم ومتابعة الطلبات","📋","requests"],["الرسائل الحكومية","البريد الداخلي","✉️","messages"],["البلاغات والأمن","الخدمات الأمنية","🛡️","security"],["القضاء والمحاكم","خدمات القضاء","⚖️","courts"],["التعليم","خدمات التعليم","📚","education"],["الصحة","الخدمات الصحية","🏥","health"],["البلديات","الخدمات البلدية","🏙️","municipality"],["العقارات والأراضي","خدمات الأراضي","🏠","land"],["التجارة","السجلات والخدمات التجارية","🏬","commerce"],["الفروع التجارية","إدارة الفروع","🏪","commerce-branches"],["التوظيف","الوظائف والتقديم","💼","jobs"],["خدمات الموظفين","الموظفون والصلاحيات","👥","staff"],["رواتب الموظفين","إدارة الرواتب","💰","payroll"],["خزائن الشركات","الحسابات المالية للشركات","▤","company-treasury"],["موظفو الشركات","إدارة موظفي الشركات","♙","company-staff"],["ميزانيات الدولة","إدارة الميزانيات","📊","state-budgets"],["الإعلانات والقرارات","الأخبار والقرارات الرسمية","📰","news"],["مكتب الخدمات","خدمة المراجعين","🎫","service-desk"]];
const govColors=['#0e4d3a','#7a3a1a','#2b5b6b'];
function hero(){return `<section class="hero"><div class="wrap heroInner"><div><div class="eyebrow">بوابة حكومية موحدة · عربية أصيلة</div><h1>مرحبًا بكم في بوابة دولة المملكة العربية الصالية</h1><p>منصة موحدة للخدمات الحكومية والجهات الرسمية والقطاع الخاص والخدمات الرقمية.</p><form id="searchForm" class="search"><input id="searchBox" aria-label="البحث" placeholder="ابحث عن خدمة أو وزارة أو محافظة…" required><button class="btn" type="submit">بحث</button></form><div class="actions"><a class="btn gold" href="#/services">الدخول إلى الخدمات</a><a class="btn" href="#/ministries">استعراض الجهات الحكومية</a></div></div><div class="ornament" aria-hidden="true">◇</div></div></section>`}
function govCards(){return `<div class="grid">${data.governorates.map((g,i)=>`<a class="card govCard link" href="#/gov/${safe(g.id)}"><div class="govTop k" style="background:${govColors[i]}">${safe(g.name)}</div><div class="body"><b>${safe(g.description)}</b><div class="muted">المحافظ: ${safe(g.governor)}</div></div></a>`).join('')}</div>`}
function ministryCards(items=data.ministries){return `<div class="directory">${items.map(m=>`<a href="#/ministry/${m.id}"><b>${safe(m.name)}</b><small>${safe(m.minister)}</small></a>`).join('')}</div>`}
function newsCards(){return data.news.length?`<div class="grid">${data.news.map(n=>`<article class="card"><div class="tag">${({news:'خبر',decree:'قرار ملكي',circular:'تعميم'})[n.kind]}</div><h3>${safe(n.title)}</h3><div class="muted">${safe(n.created_at)}</div><p class="article">${safe(n.body)}</p></article>`).join('')}</div>`:'<div class="empty">لا توجد أخبار أو قرارات منشورة حتى الآن.</div>'}
function home(){app.innerHTML=hero()+`<div class="wrap"><div class="notice"><b>تنبيه وطني:</b> لا يوجد تنبيه نشط حاليًا.</div><section class="section" id="services"><h2>خدمات مختارة</h2><div class="muted">الخدمات المرتبطة بالسجل الرسمي للمستخدم</div>${serviceCards(services.slice(0,6))}<p><a class="btn outline" href="#/services">عرض جميع الخدمات</a></p></section><section class="section"><h2>استكشف المحافظات</h2>${govCards()}</section><section class="section"><h2>الوزارات والهيئات</h2><div class="muted">35 وزارة · هيئة الطيران المدني تحت إشراف الملك المباشر</div>${ministryCards(data.ministries.slice(0,9))}<div class="actions"><a class="btn outline" href="#/ministries">عرض دليل الجهات كاملًا</a></div></section><section class="section"><h2>البنوك</h2><p class="muted">حسابات وتحويلات داخلية بالريال الصالي.</p><a class="btn outline" href="#/banking">دخول البنوك</a> <a class="btn outline" href="#/cards-atm">البطاقات والصرافات</a> <a class="btn outline" href="#/pos">نقاط البيع</a> <a class="btn outline" href="#/installments">تابي وتمارا الصالية</a></section><section class="section"><h2>التوظيف</h2><p class="muted">استعرض الوظائف الحكومية والخاصة والعسكرية وتابع طلباتك.</p><a class="btn outline" href="#/jobs">بوابة التوظيف</a></section><section class="section"><h2>الأخبار والقرارات</h2>${newsCards()}</section><section class="section"><h2>مؤشرات الدولة</h2><div class="muted">تظهر البيانات الحقيقية عند اكتمال ربط الأنظمة.</div><div class="grid">${['المواطنون','المقيمون','الطلبات المنجزة'].map(x=>`<div class="card"><div class="muted">${x}</div><h2>—</h2></div>`).join('')}</div></section></div>`;document.querySelector('#searchForm').onsubmit=e=>{e.preventDefault();location.hash='#/ministries?q='+encodeURIComponent(document.querySelector('#searchBox').value)}}
function serviceCards(items=services){return `<div class="grid">${items.map(([n,d,i,route])=>`<a class="card link" href="#/${route}"><div class="icon">${i}</div><h3>${safe(n)}</h3><div class="muted">${safe(d)}</div></a>`).join('')}</div>`}
function page(title,body){app.innerHTML=`<div class="wrap page"><a class="muted" href="#/">الرئيسية</a><h1>${title}</h1>${body}</div>`}
function showMinistries(query=''){page('دليل الوزارات والهيئات',`<label class="field"><span>بحث عن وزارة أو وزير</span><input class="input" id="filter" value="${safe(query)}" placeholder="اكتب اسم الوزارة أو الوزير"></label><div id="results">${ministryCards(data.ministries.filter(m=>(m.name+m.minister).includes(query)))}</div><p class="muted">هيئة الطيران المدني تحت الإشراف المباشر للملك.</p>`);document.querySelector('#filter').oninput=e=>{const q=e.target.value;document.querySelector('#results').innerHTML=ministryCards(data.ministries.filter(m=>(m.name+m.minister).includes(q)))}}
async function citizenProfile(){if(!me){location.hash='#/login';return}const r=await api('/citizen/profile');if(!r.profile){page('ملفي كمواطن','لا يوجد ملف مواطن مرتبط بهذا الحساب');return}page('ملفي كمواطن','<div class="card"><p>الاسم: '+safe(r.profile.full_name)+'</p><p>رقم الهوية: '+safe(r.profile.number)+'</p><form id="citizenPhone" class="form"><label class="field">رقم الجوال (اختياري)<input class="input" name="phone" type="tel" value="'+safe(r.profile.phone||'')+'"></label><button class="btn">حفظ رقم الجوال</button><p role="status"></p></form></div>');document.querySelector('#citizenPhone').onsubmit=async e=>{e.preventDefault();try{await post('/citizen/profile/phone',{phone:new FormData(e.target).get('phone')});e.target.querySelector('[role=status]').textContent='تم حفظ رقم الجوال'}catch(err){e.target.querySelector('[role=status]').textContent=err.message}}}
async function ministryOffice(){
 if(!me){location.hash='#/login';return}
 try{
  const available=await api('/ministry-office/ministries');
  const ministries=available.ministries||[];
  if(!ministries.length){page('مكتب الوزير','لا توجد وزارات مرتبطة بهذا الحساب');return}
  const records=await Promise.all(ministries.map(m=>api('/ministry-office/actions?ministry_id='+m.id)));
  const sections=ministries.map((m,i)=>{
   const actions=records[i].actions||[];
   return '<section class="card"><h2>'+safe(m.name)+'</h2><p>الوزير: '+safe(m.minister)+'</p><form class="form ministry-action-form" data-ministry-id="'+m.id+'"><label class="field">موضوع المعاملة<input class="input" name="subject" required minlength="3"></label><label class="field">التفاصيل<textarea class="input" name="details" rows="4"></textarea></label><label class="field">الحالة<select class="input" name="status"><option value="draft">مسودة</option><option value="submitted">رفع للمراجعة</option></select></label><button class="btn gold">حفظ معاملة '+safe(m.name)+'</button><p role="status"></p></form><h3>معاملات الوزارة</h3>'+(actions.length?actions.map(x=>'<div class="card"><b>'+safe(x.subject)+'</b><p>'+safe(x.details)+'</p><small>'+safe(x.status)+'</small></div>').join(''):'<p>لا توجد معاملات حتى الآن</p>')+'</section>';
  }).join('');
  page('مكتب الوزير','<div class="notice">وزاراتك المسجلة تظهر تلقائيًا عند الدخول، وعددها '+ministries.length+'. كل وزارة مستقلة بمعاملاتها وصلاحياتها.</div>'+sections);
  document.querySelectorAll('.ministry-action-form').forEach(form=>{form.onsubmit=async e=>{e.preventDefault();try{await post('/ministry-office/actions',{...Object.fromEntries(new FormData(form)),ministry_id:Number(form.dataset.ministryId)});await ministryOffice()}catch(err){form.querySelector('[role=status]').textContent=err.message}}});
 }catch(err){page('مكتب الوزير','<div class="notice">'+safe(err.message)+'</div>')}
}
async function ministryAccounts(){
 if(me?.role!=='king'){page('غير مخول','للملك فقط');return}
 try{
 const [roster,accounts]=await Promise.all([api('/admin/ministries/roster'),api('/ministries/accounts')]);
 page('حسابات الوزارات',`<div class="notice">اختر الوزير، وستظهر وزاراته المسجلة تلقائيًا. ضع كلمة مرور خاصة به ثم أنشئ حسابه.</div><form id="ministerCreate" class="card form"><label class="field">اسم الوزير<select class="input" name="minister_id" id="ministerSelect" required><option value="">اختر الوزير</option>${roster.ministers.map(m=>`<option value="${m.id}" ${m.created?'disabled':''}>${safe(m.name)}${m.created?' (حساب موجود)':''}</option>`).join('')}</select></label><div id="ministerOwned" class="notice">اختر الوزير لعرض وزاراته</div><label class="field">اسم المستخدم<input class="input" id="ministerUsername" readonly></label><label class="field">كلمة المرور للوزير<input class="input" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><button class="btn gold" type="submit">إنشاء حساب الوزير</button><p id="ministerCreateResult" role="status"></p></form><h2>الحسابات المنشأة</h2>${accounts.accounts.map(a=>`<div class="card"><b>${safe(a.minister)}</b><p>${a.ministries.map(safe).join('، ')}</p><p>اسم المستخدم: ${safe(a.username)}</p></div>`).join('')}`);
 const select=document.querySelector('#ministerSelect');
 select.onchange=()=>{const m=roster.ministers.find(x=>x.id===Number(select.value));document.querySelector('#ministerOwned').textContent=m?'الوزارات: '+m.ministries.join('، '):'اختر الوزير لعرض وزاراته';document.querySelector('#ministerUsername').value=m?.username||''};
 document.querySelector('#ministerCreate').onsubmit=async e=>{e.preventDefault();const result=document.querySelector('#ministerCreateResult');const id=Number(select.value);if(!select.value){result.textContent='اختر الوزير أولًا';return}const password=e.target.elements.password.value;try{const r=await post('/admin/ministries/provision',{minister_id:id,password});result.textContent='تم إنشاء حساب '+r.minister+' باسم المستخدم '+r.username+'؛ احتفظ بكلمة المرور التي اخترتها.';e.target.elements.password.value='';select.querySelector('option[value="'+id+'"]').disabled=true}catch(err){result.textContent=err.message}};
 }catch(err){page('حسابات الوزارات','<div class="notice">'+safe(err.message)+'</div>')}
}
function citizenRegister(){page('إنشاء حساب مواطن','<div class="notice">أصدر الهوية الوطنية أولًا من الأحوال، واطلب رمز تفعيل صالحًا لمدة 14 يومًا.</div><form id="citizenRegister" class="card form"><label class="field">رقم الهوية<input class="input" name="document_number" required></label><label class="field">رمز التفعيل<input class="input" name="activation_code" required></label><label class="field">اسم المستخدم<input class="input" name="username" pattern="[A-Za-z0-9_]+" required></label><label class="field">كلمة المرور<input class="input" type="password" name="password" minlength="12" required></label><label class="field">الجوال (اختياري)<input class="input" name="phone" type="tel"></label><button class="btn gold">إنشاء الحساب</button><p role="status"></p></form>');document.querySelector('#citizenRegister').onsubmit=async e=>{e.preventDefault();try{await post('/auth/citizen/register',Object.fromEntries(new FormData(e.target)));e.target.querySelector('[role=status]').textContent='تم إنشاء الحساب، سجل الدخول الآن'}catch(err){e.target.querySelector('[role=status]').textContent=err.message}}}
function login(){page('تسجيل الدخول',`<form id="loginForm" class="card form"><label class="field"><span>اسم المستخدم</span><input class="input" name="username" autocomplete="username" required></label><label class="field"><span>كلمة المرور</span><input class="input" name="password" type="password" autocomplete="current-password" required></label><button class="btn" type="submit">دخول</button><p id="msg" role="status"></p></form>`);document.querySelector('#loginForm').insertAdjacentHTML('beforeend','<p><a href="#/recover-owner">استرداد حساب الملك</a> · <a href="#/citizen-register">إنشاء حساب مواطن</a></p>');document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await post('/auth/login',Object.fromEntries(f));await refreshUser();location.hash='#/dashboard'}catch(err){document.querySelector('#msg').textContent=err.message}}}
async function recoverOwner(){page('استرداد حساب الملك',`<div class="notice">استرداد آمن لحساب الملك الحالي مع الحفاظ على بياناته. يتطلب رمز التهيئة الموجود في إعدادات Cloudflare.</div><form id="recoverOwnerForm" class="card form"><label class="field">رمز التهيئة<input class="input" name="setup_secret" type="password" autocomplete="off" required></label><label class="field">كلمة مرور جديدة (12 حرفًا على الأقل)<input class="input" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><button class="btn gold" type="submit">استرداد حساب الملك</button><p id="msg" role="status"></p></form>`);document.querySelector('#recoverOwnerForm').onsubmit=async e=>{e.preventDefault();try{await post('/setup/recover-owner',Object.fromEntries(new FormData(e.target)));document.querySelector('#msg').textContent='تم الاسترداد بنجاح. يمكنك تسجيل الدخول الآن.';e.target.reset()}catch(err){document.querySelector('#msg').textContent=err.message}}}
async function setup(){const status=await api('/setup/status');if(!status.needsSetup){page('التهيئة مكتملة','<p>تم إنشاء الحساب الأول مسبقًا. <a href="#/login">تسجيل الدخول</a></p>');return}page('التهيئة الأولى — حساب الملك',`<div class="notice">تُستخدم هذه الصفحة مرة واحدة فقط، قبل إنشاء أي حساب. اختر كلمة مرور قوية ولا تشاركها.</div><form id="setupForm" class="card form"><label class="field"><span>رمز التهيئة السري من إعدادات Cloudflare</span><input class="input" name="setup_secret" type="password" required></label><label class="field"><span>اسم المستخدم الملكي</span><input class="input" name="username" minlength="3" maxlength="40" pattern="[A-Za-z0-9_]+" required></label><label class="field"><span>كلمة المرور (12 حرفًا على الأقل)</span><input class="input" name="password" type="password" minlength="12" autocomplete="new-password" required></label><button class="btn gold">إنشاء حساب الملك</button><p id="msg" role="status"></p></form>`);document.querySelector('#setupForm').onsubmit=async e=>{e.preventDefault();try{await post('/setup/king',Object.fromEntries(new FormData(e.target)));location.hash='#/login'}catch(err){document.querySelector('#msg').textContent=err.message}}}
async function dashboard(){if(!me){location.hash='#/login';return}let content=`<p>مرحبًا، ${safe(me.username)} · الصلاحية: ${safe(me.role)}</p><div class="actions"><a class="btn" href="#/requests">الطلبات والمتابعة</a><a class="btn outline" href="#/jobs">الوظائف</a><a class="btn outline" href="#/education">التعليم</a><a class="btn outline" href="#/payroll">رواتبي</a><a class="btn outline" href="#/state-budgets">مقترحات الميزانيات</a><a class="btn outline" href="#/courts">القضاء والمحاماة</a><a class="btn outline" href="#/messages">الرسائل الحكومية</a><a class="btn outline" href="#/service-desk">مركز خدمة المواطنين</a><a class="btn outline" href="#/health">الصحة والمواعيد</a><a class="btn outline" href="#/municipality">البلديات والرخص</a><a class="btn outline" href="#/land">العقارات والملكية</a><a class="btn outline" href="#/commerce">السجل التجاري والشركات</a><a class="btn outline" href="#/commerce-branches">فروع الشركات</a><a class="btn outline" href="#/company-treasury">حسابات الشركات</a><a class="btn outline" href="#/company-staff">موظفو الشركات ورواتبهم</a><a class="btn outline" href="#/security">أمان الحساب والجلسات</a><a class="btn outline" href="#/telecom">الجوال والاتصالات</a><button class="btn outline" id="logout">تسجيل الخروج</button></div>`;if(me.role==='king'){content+=`<section class="card"><h2>القرارات المالية والإدارية</h2><p>إدارة قضايا المديونيات وطلبات إيقاف الخدمات ومتابعة الاعتماد.</p><a class="btn gold" href="#/enforcement">فتح إدارة المديونيات وإيقاف الخدمات</a></section>`;const o=await api('/admin/overview');content+=`<div class="actions"><a class="btn" href="#/borders">المنافذ والجمارك</a><a class="btn" href="#/registry">الوثائق والتعاميم</a><a class="btn" href="#/civil">طلبات الأحوال</a><a class="btn" href="#/audit">سجل التدقيق</a><a class="btn" href="#/staff">إدارة الموظفين</a><a class="btn" href="#/jobs-admin">إدارة التوظيف</a><a class="btn" href="#/payroll">الرواتب والميزانيات</a><a class="btn" href="#/state-budgets">اعتماد ميزانية الدولة</a><a class="btn" href="#/bank-admin">إدارة أرصدة البنوك</a><a class="btn gold" href="#/enforcement">المديونيات وإيقاف الخدمات</a><a class="btn" href="#/readiness">فحص جاهزية الإطلاق</a></div><h2>الملك وإدارة الدولة</h2><div class="stats"><div class="stat">الحسابات<b>${o.users}</b></div><div class="stat">الطلبات<b>${o.requests}</b></div><div class="stat">المنشورات<b>${o.news}</b></div></div><div class="actions"><a class="btn gold" href="#/publish">نشر خبر أو قرار</a></div>`}else if(me.role==='employee'){content+=`<div class="actions"><a class="btn" href="#/borders">المنافذ والجمارك</a><a class="btn" href="#/registry">الوثائق</a><a class="btn" href="#/civil">الأحوال</a><a class="btn" href="#/publish">النشر</a></div>`}if(me.role==='king')content+='<p><a class="btn gold" href="#/ministry-accounts">إدارة حسابات الوزارات</a></p>';if(me.role==='employee')content+='<p><a class="btn gold" href="#/ministry-office">مكتب الوزارة</a> <a class="btn" href="#/enforcement">المديونيات وإيقاف الخدمات (للداخلية والعدل والمالية)</a></p>';if(me.role==='citizen')content+='<p><a class="btn gold" href="#/citizen-profile">ملفي كمواطن · تعديل رقم الجوال</a></p>';page('لوحة التحكم',content);document.querySelector('#logout').onclick=async()=>{await post('/auth/logout',{});await refreshUser();location.hash='#/'}}
async function requests(){if(!me){location.hash='#/login';return}const result=await api('/requests');page('الطلبات والمتابعة',`<form class="card form" id="requestForm"><h3>طلب جديد</h3><label class="field"><span>نوع الطلب</span><select class="input" name="kind"><option value="diwan">الديوان الملكي</option><option value="complaint">شكوى</option><option value="suggestion">مقترح</option></select></label><label class="field"><span>الموضوع</span><input class="input" name="subject" required minlength="3" maxlength="150"></label><label class="field"><span>التفاصيل</span><textarea class="input" name="description" required minlength="5" maxlength="3000" rows="4"></textarea></label><button class="btn">تسجيل الطلب</button><p id="msg" role="status"></p></form><h2>سجل الطلبات</h2>${result.requests.length?result.requests.map(r=>`<div class="card"><b>${safe(r.subject)}</b><div class="muted">رقم الطلب: ${safe(r.id)} · الحالة: ${safe(r.status)} · ${safe(r.created_at)}</div><p>${safe(r.description)}</p></div>`).join(''):'<p class="empty">لا توجد طلبات بعد.</p>'}`);document.querySelector('#requestForm').onsubmit=async e=>{e.preventDefault();try{const r=await post('/requests',Object.fromEntries(new FormData(e.target)));document.querySelector('#msg').textContent='تم تسجيل الطلب: '+r.id;setTimeout(()=>route(),500)}catch(err){document.querySelector('#msg').textContent=err.message}}}
async function publish(){if(!me){location.hash='#/login';return}page('نشر خبر أو قرار',`<form class="card form" id="publishForm"><label class="field"><span>نوع المنشور</span><select class="input" name="kind"><option value="news">خبر</option><option value="decree">قرار ملكي</option><option value="circular">تعميم</option></select></label><label class="field"><span>العنوان</span><input class="input" name="title" required maxlength="160"></label><label class="field"><span>النص</span><textarea class="input" name="body" rows="6" required maxlength="6000"></textarea></label><button class="btn gold">نشر</button><p id="msg"></p></form>`);document.querySelector('#publishForm').onsubmit=async e=>{e.preventDefault();try{await post('/admin/news',Object.fromEntries(new FormData(e.target)));await refreshData();location.hash='#/news'}catch(err){document.querySelector('#msg').textContent=err.message}}}

function formHandler(id,path,after){document.querySelector('#'+id).onsubmit=async e=>{e.preventDefault();const msg=e.target.querySelector('[role=status]');try{const r=await post(path,Object.fromEntries(new FormData(e.target)));msg.textContent=after?after(r):'تم حفظ العملية بنجاح';msg.className='success';e.target.reset()}catch(err){msg.textContent=err.message;msg.className='error'}}}
async function registry(){if(!me){location.hash='#/login';return}const [docs,apps,civil]=await Promise.all([api('/registry/documents'),api('/registry/applications'),api('/registry/approved-civil')]);page('الوثائق والتعاميم',`<div class="notice">وثائق المملكة الصالية افتراضية. رقم الهوية أو الإقامة أو الجواز لا يصدر إلا بعد الموافقة على الطلب.</div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,310px),1fr))"><form id="checkDoc" class="card"><h3>فحص وثيقة</h3><label class="field">رقم الوثيقة<input class="input" name="number" required></label><label class="field">سبب الفحص<input class="input" name="reason" value="فحص إداري"></label><button class="btn">فحص</button><p role="status"></p></form><form id="newDocApplication" class="card"><h3>طلب إصدار وثيقة</h3><label class="field">طلب الأحوال المعتمد<select class="input" name="civil_intake_id" id="civilSource"><option value="">إدخال يدوي</option>${civil.applications.map(c=>`<option value="${safe(c.id)}">${safe(c.reference)} — ${safe(c.full_name)}</option>`).join('')}</select></label><label class="field">النوع<select class="input" name="type"><option value="national_id">هوية وطنية</option><option value="residency">إقامة</option><option value="passport">جواز سفر</option></select></label>${[['full_name','الاسم الكامل'],['nationality','الجنسية'],['issuer','جهة الإصدار']].map(([n,t])=>`<label class="field">${t}<input class="input" name="${n}" required></label>`).join('')}<label class="field">تاريخ الميلاد<input class="input" name="birth_date" type="date" required></label><label class="field">مكان الميلاد<input class="input" name="birth_place" maxlength="160" required></label><label class="field">الجنس<select class="input" name="gender" required><option value="">اختر الجنس</option><option value="male">ذكر</option><option value="female">أنثى</option></select></label><label class="field">اسم الأب<input class="input" name="father_name" maxlength="160" required></label><label class="field">اسم الأم<input class="input" name="mother_name" maxlength="160" required></label><label class="field">تاريخ الانتهاء<input class="input" name="expires_at" type="date" required></label><label class="field">الجوال (اختياري)<input class="input" name="phone" type="tel"></label><button class="btn">إرسال الطلب للمراجعة</button><p role="status"></p></form><form id="newCircular" class="card"><h3>تعميم على وثيقة</h3>${[['reference','رقم التعميم'],['document_number','رقم الوثيقة'],['kind','نوع التعميم'],['reason','السبب']].map(([n,t])=>`<label class="field">${t}<input class="input" name="${n}" required></label>`).join('')}<label class="field">السرية<select class="input" name="confidentiality"><option value="restricted">مقيد</option><option value="public">عام</option></select></label><button class="btn">إصدار تعميم</button><p role="status"></p></form></div><h2>تفعيل حساب المواطن</h2><form id="activationForm" class="card form"><label class="field">رقم الهوية أو الإقامة أو الجواز أو معرّف الوثيقة<input class="input" name="document_id" required></label><button class="btn">إصدار رمز التفعيل</button><p role="status"></p></form><h2>طلبات الإصدار</h2><div class="directory">${apps.applications.map(x=>`<div class="card"><b>${safe(x.full_name)}</b><p>${safe(x.reference)} · ${safe(x.type)}</p><p>الحالة: ${safe(x.status)}${x.document_number?' · رقم الوثيقة: '+safe(x.document_number):''}</p>${x.status==='pending'?`<button class="btn" data-docdecision="approved" data-id="${safe(x.id)}">قبول وإصدار الرقم</button> <button class="btn" data-docdecision="rejected" data-id="${safe(x.id)}">رفض</button>`:''}</div>`).join('')||'<p>لا توجد طلبات.</p>'}</div><h2>الوثائق الصادرة</h2><div class="directory">${docs.documents.map(d=>`<div class="card"><b>${safe(d.full_name)}</b><p>${safe(d.type)} · ${safe(d.number)}</p><p class="muted">معرّف الوثيقة: ${safe(d.id)}</p><form class="docPhone" data-id="${safe(d.id)}"><input class="input" name="phone" type="tel" placeholder="رقم الجوال (اختياري)" value="${safe(d.phone||'')}"><button class="btn outline">حفظ الجوال</button><p role="status"></p></form><small>الصلاحية: ${safe(d.expires_at)} · ${safe(d.status)}</small></div>`).join('')||'<p>لا توجد وثائق.</p>'}</div>`);formHandler('checkDoc','/registry/check',r=>'النتيجة: '+({valid:'سارية',unregistered:'غير مسجلة',expired:'منتهية',cancelled:'ملغاة',suspended:'موقوفة',circular:'يوجد تعميم نشط'}[r.result]||r.result));document.querySelector('#activationForm').onsubmit=async e=>{e.preventDefault();try{const r=await post('/registry/citizen-activation',Object.fromEntries(new FormData(e.target)));e.target.querySelector('[role=status]').textContent='رمز التفعيل (انسخه الآن): '+r.activation_code+' — صالح 14 يومًا'}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};document.querySelectorAll('.docPhone').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await post('/registry/documents/phone',{id:form.dataset.id,phone:new FormData(form).get('phone')});form.querySelector('[role=status]').textContent='تم الحفظ'}catch(err){form.querySelector('[role=status]').textContent=err.message}});document.querySelector('#civilSource').onchange=e=>{const c=civil.applications.find(x=>x.id===e.target.value);if(!c)return;const f=document.querySelector('#newDocApplication');for(const [k,v] of Object.entries({full_name:c.full_name,birth_date:c.birth_date,father_name:c.parent_name})){if(v&&f.elements[k])f.elements[k].value=v}};formHandler('newDocApplication','/registry/applications',r=>'تم تقديم الطلب للمراجعة: '+r.reference);formHandler('newCircular','/registry/circulars',r=>'تم إصدار التعميم: '+r.id);document.querySelectorAll('[data-docdecision]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm(btn.dataset.docdecision==='approved'?'تأكيد قبول الطلب وإصدار رقم الوثيقة؟':'تأكيد رفض الطلب؟'))return;btn.disabled=true;try{const r=await api('/registry/applications/decision',{method:'POST',body:JSON.stringify({id:btn.dataset.id,decision:btn.dataset.docdecision})});alert(r.number?'تم الاعتماد وإصدار الرقم: '+r.number:'تم رفض الطلب');await registry()}catch(e){alert(e.message);btn.disabled=false}}))}
async function civil(){
 if(!me){location.hash='#/login';return}
 try{
 const r=await api('/civil/intake');
 page('تسجيل ومراجعة طلبات الأحوال المدنية',`<div class="actions"><a class="btn gold" href="#/family-cards">كرت العائلة — إصدار وتجديد</a></div><div class="notice">قبول طلب الأحوال يعني الموافقة على مراجعته إداريًا، ولا يصدر هوية تلقائيًا. إصدار الهوية يتم من قسم الوثائق والتعاميم.</div><form class="card form" id="civilForm"><label class="field">الاسم الكامل<input class="input" name="full_name" required></label><label class="field">اسم ولي الأمر (اختياري)<input class="input" name="parent_name"></label><label class="field">تاريخ الميلاد (اختياري)<input class="input" name="birth_date" type="date"></label><label class="field">ملاحظات الطلب<textarea class="input" name="details" rows="3"></textarea></label><button class="btn">تسجيل الطلب</button><p role="status"></p></form><h2>مراجعة واعتماد الطلبات</h2>${r.applications.map(x=>`<div class="card"><b>${safe(x.full_name)}</b><p>${safe(x.reference)} · الحالة: ${safe(x.status)}</p><p>${safe(x.details||'')}</p>${['recorded','reviewing'].includes(x.status)?`<form class="civil-review" data-id="${safe(x.id)}"><label class="field">ملاحظة المراجع / سبب الرفض<textarea class="input" name="note" rows="2"></textarea></label><div class="actions"><button class="btn" name="decision" value="reviewing" type="submit">قيد المراجعة</button><button class="btn gold" name="decision" value="approved" type="submit">اعتماد</button><button class="btn" name="decision" value="rejected" type="submit">رفض</button></div><p role="status"></p></form>`:`<p>قرار نهائي ${safe(x.review_note||'')}</p>`}</div>`).join('')||'<p class="empty">لا توجد طلبات بعد.</p>'}`);
 formHandler('civilForm','/civil/intake',x=>'تم تسجيل الطلب: '+x.reference);
 document.querySelectorAll('.civil-review').forEach(form=>{form.querySelectorAll('button[name=decision]').forEach(btn=>{btn.onclick=async e=>{e.preventDefault();const note=form.elements.note.value.trim();if(btn.value==='rejected'&&!note){form.querySelector('[role=status]').textContent='سبب الرفض مطلوب';return}btn.disabled=true;try{await post('/civil/intake/decision',{id:form.dataset.id,decision:btn.value,note});await civil()}catch(err){form.querySelector('[role=status]').textContent=err.message;btn.disabled=false}}})});
 }catch(err){page('طلبات الأحوال','<div class="notice">'+safe(err.message)+'</div>')}
}
async function familyCards(){if(!me){location.hash='#/login';return}const r=await api('/civil/family-cards');const childInputs=(names=[])=>Array.from({length:10},(_,i)=>'<label class="field">الابن / الابنة '+(i+1)+' (اختياري)<input class="input" name="child" maxlength="160" value="'+safe(names[i]||'')+'"></label>').join('');page('كرت العائلة — سجل الأسرة','<div class="notice">سجل الأسرة بلا تاريخ انتهاء. التجديد عند تغيير البيانات فقط. رسوم إصدار وتجديد الوثيقة: 0 ريال. أجور التوصيل في أبشر السعودي لبعض الخدمات 39.91 ريال، وليست رسوم تجديد.</div><form class="card form" id="familyIssue"><h3>إصدار كرت عائلة</h3><label class="field">اسم الأب<input class="input" name="father_name" required></label><label class="field">اسم الأم<input class="input" name="mother_name" required></label>'+'<label class="field">الجوال (اختياري)<input class="input" name="phone" type="tel"></label>'+childInputs()+'<button class="btn gold">إصدار كرت العائلة</button><p role="status"></p></form><h2>سجلات الأسرة</h2>'+r.cards.map(x=>'<div class="card"><b>'+safe(x.number)+'</b><div class="muted">الأب: '+safe(x.father_name)+' · الأم: '+safe(x.mother_name)+' · النسخة '+safe(x.revision)+'</div><p>الأبناء: '+safe(x.children.join('، ')||'لا يوجد')+'</p><details><summary>تجديد عند تغير بيانات الأسرة</summary><form class="form familyRenew" data-id="'+safe(x.id)+'"><label class="field">اسم الأب<input class="input" name="father_name" value="'+safe(x.father_name)+'" required></label><label class="field">اسم الأم<input class="input" name="mother_name" value="'+safe(x.mother_name)+'" required></label>'+'<label class="field">الجوال (اختياري)<input class="input" name="phone" value="'+safe(x.phone||'')+'"></label>'+childInputs(x.children)+'<label class="field">سبب التغيير<input class="input" name="reason" required minlength="3" maxlength="300" placeholder="إضافة مولود أو تعديل بيانات"></label><button class="btn">تجديد السجل مجانًا</button><p role="status"></p></form></details></div>').join('')+'<p><a href="#/civil" class="btn outline">العودة للأحوال المدنية</a></p>');const getChildren=f=>f.getAll('child').map(x=>String(x).trim()).filter(Boolean);document.querySelector('#familyIssue').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await post('/civil/family-cards',{father_name:f.get('father_name'),mother_name:f.get('mother_name'),children:getChildren(f),phone:f.get('phone')});await familyCards()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};document.querySelectorAll('.familyRenew').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);try{await post('/civil/family-cards/renew',{id:form.dataset.id,father_name:f.get('father_name'),mother_name:f.get('mother_name'),children:getChildren(f),reason:f.get('reason'),phone:f.get('phone')});await familyCards()}catch(err){form.querySelector('[role=status]').textContent=err.message}})}
async function auditPage(){if(!me){location.hash='#/login';return}const r=await api('/admin/audit');page('سجل التدقيق',r.entries.map(x=>`<div class="card"><b>${safe(x.action)}</b><div class="muted">${safe(x.created_at)} · ${safe(x.entity_type)} · ${safe(x.actor_id||'نظام')}</div></div>`).join('')||'<p class="empty">لا توجد عمليات.</p>')}

async function messages(){if(!me){location.hash='#/login';return}const r=await api('/messages');page('البريد الحكومي الداخلي',`<div class="notice">المراسلات داخل نظام المملكة الصالية فقط، ولا تُرسل كرسائل SMS حقيقية.</div><form class="card form" id="messageForm"><h3>رسالة جديدة</h3><label class="field">اسم مستخدم المستلم<input class="input" name="recipient" required></label><label class="field">الموضوع<input class="input" name="subject" required minlength="3" maxlength="150"></label><label class="field">الرسالة<textarea class="input" name="body" required maxlength="3000" rows="4"></textarea></label><button class="btn">إرسال</button><p role="status"></p></form><h2>الوارد</h2>${r.messages.map(m=>`<article class="card"><b>${safe(m.subject)}</b><div class="muted">من: ${safe(m.sender||'النظام')} · ${safe(m.created_at)} · ${m.read_at?'مقروءة':'جديدة'}</div><p class="article">${safe(m.body)}</p>${m.read_at?'':`<button class="btn outline readMessage" data-id="${safe(m.id)}">تحديد كمقروءة</button>`}</article>`).join('')||'<p class="empty">لا توجد رسائل.</p>'}`);formHandler('messageForm','/messages/send',r=>'تم الإرسال: '+r.id);document.querySelectorAll('.readMessage').forEach(b=>b.onclick=async()=>{await post('/messages/read',{id:b.dataset.id});await messages()})}
async function staff(){if(me?.role!=='king'){page('غير مخوّل','<p>إدارة الموظفين للملك فقط.</p>');return}const r=await api('/admin/staff');const choices=[['registry','الوثائق والتعاميم'],['civil','تسجيل الأحوال'],['requests','إدارة الطلبات'],['news','نشر الأخبار'],['borders','المنافذ'],['education','التعليم'],['banking','البنوك'],['justice','القضاء'],['police','الشرطة'],['appeals','الاستئناف والنقض'],['health','الصحة'],['municipality','البلديات'],['land','السجل العقاري'],['commerce','التجارة'],['finance','المالية'],['budget_propose','اقتراح الميزانية']];const checks=arr=>choices.map(([k,v])=>'<label style="display:block"><input type="checkbox" name="permission" value="'+k+'" '+(arr.includes(k)?'checked':'')+'> '+v+'</label>').join('');page('إدارة حسابات الموظفين','<div class="notice">تعديل حسابات الموظفين وصلاحياتهم. تغيير بيانات الدخول ينهي جلسات الموظف.</div><form class="card form" id="staffForm"><h3>إنشاء موظف</h3><label class="field">اسم المستخدم<input class="input" name="username" pattern="[A-Za-z0-9_]+" required minlength="3"></label><label class="field">كلمة المرور<input class="input" type="password" name="password" required minlength="12"></label><h3>الصلاحيات</h3>'+checks([])+'<button class="btn gold">إنشاء موظف</button><p role="status"></p></form><h2>الحسابات المسجلة</h2>'+r.staff.map(x=>'<div class="card"><b>'+safe(x.username)+'</b><div class="muted">'+safe(x.role)+' · '+safe(x.permissions||'بلا صلاحيات إضافية')+'</div>'+(x.role==='employee'?'<details><summary>تعديل الحساب والصلاحيات</summary><form class="form staffEdit" data-id="'+safe(x.id)+'"><label class="field">اسم المستخدم<input class="input" name="username" value="'+safe(x.username)+'" pattern="[A-Za-z0-9_]+" minlength="3" required></label><label class="field">كلمة مرور جديدة (اختياري)<input class="input" type="password" name="password" autocomplete="new-password" minlength="12"></label><button class="btn">حفظ الحساب</button><p role="status"></p></form><form class="form staffPermissions" data-id="'+safe(x.id)+'"><h4>الصلاحيات</h4>'+checks((x.permissions||'').split(','))+'<button class="btn gold">حفظ الصلاحيات</button><p role="status"></p></form></details>':'')+'</div>').join(''));document.querySelector('#staffForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await post('/admin/staff',{username:f.get('username'),password:f.get('password'),permissions:f.getAll('permission')});await staff()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};document.querySelectorAll('.staffEdit').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),body={id:form.dataset.id,username:f.get('username')};if(f.get('password'))body.password=f.get('password');try{await post('/admin/staff/update',body);form.querySelector('[role=status]').textContent='تم حفظ الحساب'}catch(err){form.querySelector('[role=status]').textContent=err.message}});document.querySelectorAll('.staffPermissions').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);try{await post('/admin/staff/permissions',{id:form.dataset.id,permissions:f.getAll('permission')});form.querySelector('[role=status]').textContent='تم حفظ الصلاحيات'}catch(err){form.querySelector('[role=status]').textContent=err.message}})}

async function jobs(){const r=await api('/jobs');let mine=[];if(me){mine=(await api('/jobs/mine')).applications}page('التوظيف في المملكة',`<div class="notice">الوظائف الحكومية والخاصة والعسكرية. الرواتب بالريال الصالي داخل المحاكاة.</div><div class="actions">${me?.role==='king'?'<a class="btn gold" href="#/jobs-admin">إدارة الوظائف</a>':''}</div><h2>الوظائف المتاحة</h2>${r.jobs.map(j=>`<article class="card"><div class="tag">${safe(({government:'حكومي',private:'خاص',military:'عسكري'})[j.sector])}</div><h3>${safe(j.title)}</h3><div class="muted">${safe(j.employer)} · الراتب: ${Number(j.salary).toLocaleString('ar-SA')} ريال صالي</div><p>${safe(j.description)}</p>${me?`<form class="jobApply form" data-id="${safe(j.id)}"><label class="field">نبذة عن المؤهلات والخبرة<textarea class="input" name="statement" required minlength="10" maxlength="2000"></textarea></label><button class="btn">تقديم الطلب</button><p role="status"></p></form>`:'<a class="btn outline" href="#/login">سجّل الدخول للتقديم</a>'}</article>`).join('')||'<p class="empty">لا توجد وظائف منشورة حاليًا.</p>'}${me?`<h2>طلباتي</h2>${mine.map(a=>`<div class="card"><b>${safe(a.title)}</b><div class="muted">${safe(a.employer)} · ${safe(a.status)} · ${safe(a.created_at)}</div></div>`).join('')||'<p class="empty">لم تقدم على وظيفة بعد.</p>'}`:''}`);document.querySelectorAll('.jobApply').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const st=f.querySelector('[role=status]');try{await post('/jobs/apply',{vacancy_id:f.dataset.id,statement:new FormData(f).get('statement')});st.textContent='تم تقديم الطلب بنجاح';f.querySelector('button').disabled=true}catch(err){st.textContent=err.message}})}
async function jobsAdmin(){if(me?.role!=='king'){page('غير مخوّل','<p>إدارة الوظائف للملك فقط حاليًا.</p>');return}const r=await api('/admin/jobs/applications');page('إدارة الوظائف والتوظيف',`<form class="card form" id="vacancyForm"><h2>نشر وظيفة</h2><label class="field">المسمى الوظيفي<input class="input" name="title" required minlength="3"></label><label class="field">جهة العمل<input class="input" name="employer" required></label><label class="field">القطاع<select class="input" name="sector"><option value="government">حكومي</option><option value="private">خاص</option><option value="military">عسكري</option></select></label><label class="field">الراتب بالريال الصالي<input class="input" name="salary" type="number" min="0" step="1" required></label><label class="field">الوصف والمتطلبات<textarea class="input" name="description" minlength="10" required></textarea></label><button class="btn gold">نشر الوظيفة</button><p role="status"></p></form><h2>طلبات التوظيف</h2>${r.applications.map(a=>`<div class="card"><h3>${safe(a.title)}</h3><div class="muted">${safe(a.applicant)} · ${safe(a.employer)} · ${safe(a.created_at)}</div><p>${safe(a.statement)}</p><label class="field">حالة الطلب<select class="input jobStatus" data-id="${safe(a.id)}"><option value="submitted" ${a.status==='submitted'?'selected':''}>مقدم</option><option value="reviewing" ${a.status==='reviewing'?'selected':''}>قيد المراجعة</option><option value="accepted" ${a.status==='accepted'?'selected':''}>مقبول</option><option value="rejected" ${a.status==='rejected'?'selected':''}>مرفوض</option></select></label><p class="muted statusMsg"></p></div>`).join('')||'<p class="empty">لا توجد طلبات بعد.</p>'}`);document.querySelector('#vacancyForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const v=Object.fromEntries(f);v.salary=Number(v.salary);await post('/admin/jobs',v);e.target.querySelector('[role=status]').textContent='نُشرت الوظيفة بنجاح';e.target.reset()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};document.querySelectorAll('.jobStatus').forEach(el=>el.onchange=async()=>{const msg=el.closest('.card').querySelector('.statusMsg');try{await post('/admin/jobs/application/status',{id:el.dataset.id,status:el.value});msg.textContent='تم تحديث الحالة وإشعار المتقدم'}catch(err){msg.textContent=err.message}})}
async function banking(){if(!me){location.hash='#/login';return}const [a,t]=await Promise.all([api('/banking/accounts'),api('/banking/transfers')]);const names={saliyah:'بنك الصالية',national:'البنك الوطني الصالي',development:'بنك التنمية الصالي'};page('البنوك والمحافظ المالية',`<div class="notice">جميع الأرصدة والتحويلات بالريال الصالي داخل المحاكاة فقط. لا توجد معاملات مالية حقيقية.</div><h2>حساباتي</h2><div class="grid">${a.accounts.map(x=>`<div class="card"><h3>${names[x.bank]}</h3><b>${Number(x.balance).toLocaleString('ar-SA')} ريال صالي</b><p class="muted">رقم الحساب: ${safe(x.id)}</p></div>`).join('')||'<p class="empty">لا توجد حسابات بعد.</p>'}</div><form class="card form" id="openBank"><h3>فتح حساب جديد</h3><label class="field">البنك<select class="input" name="bank">${Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button class="btn">فتح الحساب</button><p role="status"></p></form><form class="card form" id="sendMoney"><h3>تحويل داخلي</h3><label class="field">من حساب<select class="input" name="from" required>${a.accounts.map(x=>`<option value="${safe(x.id)}">${names[x.bank]} — ${Number(x.balance).toLocaleString('ar-SA')}</option>`).join('')}</select></label><label class="field">اسم مستخدم المستلم<input class="input" name="recipient" required minlength="3"></label><label class="field">بنك المستلم<select class="input" name="bank">${Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="field">المبلغ (ريال صالي)<input class="input" name="amount" type="number" min="1" max="100000000" step="1" required></label><label class="field">البيان<input class="input" name="memo" maxlength="200"></label><button class="btn gold" ${a.accounts.length?'':'disabled'}>تحويل</button><p role="status"></p></form><h2>آخر التحويلات</h2>${t.transfers.map(x=>`<div class="card"><b>${Number(x.amount).toLocaleString('ar-SA')} ريال صالي</b><p class="muted">من ${safe(x.sender)} إلى ${safe(x.recipient)} · ${safe(x.created_at)}</p><p>${safe(x.memo)}</p></div>`).join('')||'<p class="empty">لا توجد تحويلات بعد.</p>'}`);document.querySelector('#openBank').onsubmit=async e=>{e.preventDefault();try{await post('/banking/accounts',Object.fromEntries(new FormData(e.target)));await banking()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};document.querySelector('#sendMoney').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.amount=Number(b.amount);try{await post('/banking/transfer',b);await banking()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}}}
async function refreshData(){data=await api('/public')}async function refreshUser(){me=(await api('/me')).user;document.querySelector('#authLink').textContent=me?'لوحة التحكم':'تسجيل الدخول';document.querySelector('#authLink').href=me?'#/dashboard':'#/login'}
async function cardsAtm(){if(!me){location.hash='#/login';return}const [a,c,w]=await Promise.all([api('/banking/accounts'),api('/banking/cards'),api('/banking/atm')]);const names={saliyah:'بنك الصالية',national:'البنك الوطني الصالي',development:'بنك التنمية الصالي'};const opts=a.accounts.map(x=>`<option value="${safe(x.id)}">${names[x.bank]}</option>`).join('');page('البطاقات والصرافات',`<div class="notice">بطاقات ونقد داخلي للمحاكاة فقط، لا تعمل في أجهزة الدفع الحقيقية.</div><div class="card"><h3>النقد الذي تملكه</h3><h2>${Number(w.cash).toLocaleString('ar-SA')} ريال صالي</h2></div><h2>بطاقاتي</h2><div class="grid">${c.cards.map(x=>`<div class="card"><h3>${names[x.bank]}</h3><p>•••• ${safe(x.last4)}</p><p class="muted">${x.status==='active'?'نشطة':'مجمدة'}</p><button class="btn outline card-toggle" data-id="${safe(x.id)}" data-status="${x.status==='active'?'frozen':'active'}">${x.status==='active'?'تجميد':'إعادة تفعيل'}</button></div>`).join('')||'<p class="empty">لا توجد بطاقات.</p>'}</div><form class="card form" id="issueCard"><h3>إصدار بطاقة داخلية</h3><label class="field">الحساب<select class="input" name="account_id" required>${opts}</select></label><button class="btn" ${a.accounts.length?'':'disabled'}>إصدار بطاقة</button><p role="status"></p></form><form class="card form" id="atmForm"><h3>الصراف الداخلي</h3><label class="field">الحساب<select class="input" name="account_id" required>${opts}</select></label><label class="field">نوع العملية<select class="input" name="kind"><option value="withdraw">سحب إلى المحفظة النقدية</option><option value="deposit">إيداع من المحفظة النقدية</option></select></label><label class="field">المبلغ<input class="input" name="amount" type="number" min="1" max="1000000" step="1" required></label><button class="btn gold" ${a.accounts.length?'':'disabled'}>تنفيذ العملية</button><p role="status"></p></form><h2>آخر عمليات الصراف</h2>${w.operations.map(x=>`<div class="card"><b>${x.kind==='withdraw'?'سحب':'إيداع'} — ${Number(x.amount).toLocaleString('ar-SA')} ريال صالي</b><p class="muted">${safe(x.created_at)}</p></div>`).join('')||'<p class="empty">لا توجد عمليات.</p>'}`);for(const b of document.querySelectorAll('.card-toggle'))b.onclick=async()=>{try{await post('/banking/cards/status',{id:b.dataset.id,status:b.dataset.status});await cardsAtm()}catch(e){alert(e.message)}};for(const [sel,url] of [['#issueCard','/banking/cards'],['#atmForm','/banking/atm']])document.querySelector(sel).onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(sel==='#atmForm')data.amount=Number(data.amount);try{await post(url,data);await cardsAtm()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}}}
async function posPage(){if(!me){location.hash='#/login';return}
 const [accounts,cards,merchants,payments]=await Promise.all([api('/banking/accounts'),api('/banking/cards'),api('/pos/merchants'),api('/pos/payments')]);
 const choices=accounts.accounts.map(a=>`<option value="${safe(a.id)}">${safe(a.bank)} — ${Number(a.balance).toLocaleString('ar-SA')} ريال</option>`).join('');
 page('نقاط البيع والإيصالات',`<div class="notice">نقاط البيع تعمل داخل محاكاة المملكة الصالية فقط، ولا تقبل بطاقات أو أموالًا حقيقية. رمز الدفع يُرسل إلى البريد الداخلي.</div>
 <div class="grid"><form class="card form" id="merchantForm"><h3>تسجيل متجر</h3><label class="field">اسم المتجر<input class="input" name="name" minlength="3" maxlength="100" required></label><label class="field">حساب استقبال المدفوعات<select class="input" name="account_id">${choices}</select></label><button class="btn" ${accounts.accounts.length?'':'disabled'}>إنشاء متجر</button><p role="status"></p></form>
 <form class="card form" id="paymentForm"><h3>طلب دفع من عميل</h3><label class="field">المتجر<select class="input" name="merchant_id">${merchants.merchants.map(m=>`<option value="${safe(m.id)}">${safe(m.name)}</option>`).join('')}</select></label><label class="field">اسم مستخدم العميل<input class="input" name="customer" required></label><label class="field">المبلغ بالريال الصالي<input class="input" name="amount" type="number" min="1" max="1000000" step="1" required></label><label class="field">وصف المشتريات<input class="input" name="description" maxlength="200"></label><button class="btn gold" ${merchants.merchants.length?'':'disabled'}>إرسال طلب الدفع</button><p role="status"></p></form></div>
 <h2>طلبات الدفع والإيصالات</h2>${payments.payments.map(p=>`<div class="card"><b>${safe(p.merchant)} — ${Number(p.amount).toLocaleString('ar-SA')} ريال صالي</b><p>${safe(p.description)}</p><div class="muted">العميل: ${safe(p.customer)} · الحالة: ${p.status==='paid'?'مدفوع':p.status==='cancelled'?'ملغي':'بانتظار الدفع'} · ${safe(p.created_at)}</div><small>رقم الإيصال/الطلب: ${safe(p.id)}</small>${p.paid_at?`<div class="muted">تاريخ الدفع: ${safe(p.paid_at)}</div>`:''}
 ${p.status==='pending'&&p.customer===me.username?`<div class="actions"><input class="input" id="account-${safe(p.id)}" placeholder="رقم حسابك البنكي الصالي" aria-label="رقم الحساب البنكي" required><button class="btn pos-auth" data-id="${safe(p.id)}" ${accounts.accounts.length?'':'disabled'}>طلب رمز التأكيد</button><form class="pos-confirm" data-id="${safe(p.id)}"><input class="input" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="رمز من 6 أرقام" required><button class="btn gold">تأكيد الدفع</button><span role="status"></span></form></div>`:''}
 ${p.status==='pending'&&p.customer===me.username&&p.amount>=4&&p.amount<=5000?`<form class="pos-installment form" data-id="${safe(p.id)}"><label class="field">الشراء بالتقسيط<select class="input" name="provider"><option value="tabby">تابي الصالية</option><option value="tamara">تمارا الصالية</option></select></label><button class="btn gold">تأكيد الشراء بأربعة أقساط</button><span role="status"></span></form>`:''}
 ${p.status==='pending'?`<button class="btn outline pos-cancel" data-id="${safe(p.id)}">إلغاء الطلب</button>`:''}</div>`).join('')||'<div class="empty">لا توجد طلبات دفع.</div>'}`);
 for(const [id,path] of [['merchantForm','/pos/merchant'],['paymentForm','/pos/request']])document.getElementById(id).onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(id==='paymentForm')b.amount=Number(b.amount);try{await post(path,b);await posPage()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};
 for(const b of document.querySelectorAll('.pos-auth'))b.onclick=async()=>{try{await post('/pos/authorize',{payment_id:b.dataset.id,account_id:document.getElementById('account-'+b.dataset.id).value.trim()});b.textContent='أُرسل الرمز إلى الرسائل الداخلية'}catch(err){alert(err.message)}};
 for(const f of document.querySelectorAll('.pos-confirm'))f.onsubmit=async e=>{e.preventDefault();try{await post('/pos/confirm',{payment_id:f.dataset.id,code:new FormData(f).get('code')});await posPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};
 for(const f of document.querySelectorAll('.pos-installment'))f.onsubmit=async e=>{e.preventDefault();const provider=new FormData(f).get('provider');if(!confirm('تأكيد الشراء بالتقسيط؟ سيُودع كامل المبلغ في حساب المتجر وتصبح الأقساط مستحقة عليك.'))return;try{await post('/installments/checkout',{payment_id:f.dataset.id,provider});await posPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};
 for(const b of document.querySelectorAll('.pos-cancel'))b.onclick=async()=>{try{await post('/pos/cancel',{payment_id:b.dataset.id});await posPage()}catch(err){alert(err.message)}};
}
async function telecom(){if(!me){location.hash='#/login';return}
 const [lr,ar]=await Promise.all([api('/telecom/lines'),api('/banking/accounts')]);const lines=lr.lines,accounts=ar.accounts;
 const opts=lines.map(l=>`<option value="${safe(l.id)}">${safe(l.number)} — ${safe(l.carrier.toUpperCase())}</option>`).join('');
 const banks={saliyah:'بنك الصالية',national:'البنك الوطني الصالي',development:'بنك التنمية الصالي'};
 const accountOpts=accounts.map(a=>`<option value="${safe(a.id)}">${banks[a.bank]||safe(a.bank)} — ${Number(a.balance).toLocaleString('ar-SA')} ريال صالي</option>`).join('');
 page('الجوال والاتصالات الصالية',`<div class="actions"><a class="btn gold" href="#/absher">فتح أبشر الصالية — الخدمات الوطنية</a></div><div class="notice">خدمات رسمية داخل المملكة الصالية الافتراضية. الأسعار بالريال والهلل الصالي، ولا تُجرى مكالمات أو مدفوعات حقيقية.</div>
 <div class="grid"><form class="card form" id="newLine"><h3>إصدار شريحة</h3><label class="field">الشركة<select class="input" name="carrier"><option value="stc">STC الصالية</option><option value="zain">زين الصالية</option></select></label><button class="btn">إصدار رقم</button><p role="status"></p></form>
 <form class="card form" id="newPlan"><h3>شراء باقة وخصم رسومها</h3><label class="field">الشريحة<select class="input" name="line_id">${opts}</select></label><label class="field">الباقة<select class="input" name="plan"><option value="stc_basic">STC سوا بيسك — 34.50 ريال صالي / 1 جيجابايت</option><option value="stc_50">STC سوا 50 — 57.50 ريال صالي / 2 جيجابايت</option><option value="stc_120">STC سوا 120 — 138 ريال صالي / 45 جيجابايت</option><option value="zain_flex69">زين فليكس 69 — 79.35 ريال صالي / 10 جيجابايت</option><option value="zain_flex109">زين فليكس 109 — 125.35 ريال صالي / 35 جيجابايت</option></select></label><label class="field">الحساب الذي تُخصم منه الرسوم<select class="input" name="account_id" required>${accountOpts}</select></label><button class="btn gold" ${lines.length&&accounts.length?'':'disabled'}>شراء وتفعيل</button><p role="status"></p></form></div>
 <h2>شرائحي واستهلاك البيانات</h2><div class="grid">${lines.map(l=>`<div class="card"><h3>${safe(l.number)}</h3><p>${safe(l.carrier.toUpperCase())} · ${safe(l.plan_name||'بدون باقة')}</p><p>المستهلك: ${Math.max(0,Number(l.data_mb)-Number(l.data_remaining_mb))} ميجابايت · المتبقي: ${Number(l.data_remaining_mb)} ميجابايت</p><p class="muted">انتهاء الباقة: ${safe(l.expires_at||'—')}</p><button class="btn browse" data-line="${safe(l.id)}">تصفح صفحة صالية (1 ميجابايت)</button><p class="muted">يُخصم 1 ميجابايت عند فتح الصفحة داخل المحاكاة.</p></div>`).join('')||'<p class="empty">لا توجد شرائح.</p>'}</div>
 <h2>الرسائل الداخلية</h2><form class="card form" id="sendSms"><label class="field">من شريحة<select class="input" name="line_id">${opts}</select></label><label class="field">المستلم<input class="input" name="to_number" pattern="05[0-9]{8}" placeholder="05XXXXXXXX" required></label><label class="field">الرسالة<textarea class="input" name="body" maxlength="500" required></textarea></label><button class="btn" ${lines.length?'':'disabled'}>إرسال</button><p role="status"></p></form><div class="card"><h3>صندوق الرسائل</h3><select class="input" id="smsLine">${opts}</select><div id="smsList"></div></div>`);
 for(const [id,path] of [['newLine','/telecom/lines'],['newPlan','/telecom/plan'],['sendSms','/telecom/sms']])document.getElementById(id).onsubmit=async e=>{e.preventDefault();try{const r=await post(path,Object.fromEntries(new FormData(e.target)));if(r.receipt_id)alert('تم الخصم والتفعيل. رقم الإيصال: '+r.receipt_id);await telecom()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};
 for(const b of document.querySelectorAll('.browse'))b.onclick=async()=>{try{const r=await post('/telecom/browse',{line_id:b.dataset.line});alert('استهلكت '+r.used_mb+' ميجابايت. المتبقي '+r.remaining_mb+' ميجابايت.');await telecom()}catch(e){alert(e.message)}};
 const select=document.getElementById('smsLine');const load=async()=>{if(!select.value){document.getElementById('smsList').textContent='أصدر شريحة أولًا';return}try{const r=await api('/telecom/sms?line='+encodeURIComponent(select.value));document.getElementById('smsList').innerHTML=r.messages.map(m=>`<div class="card"><b>${safe(m.from_number)} ← ${safe(m.to_number)}</b><p>${safe(m.body)}</p></div>`).join('')||'<p>لا توجد رسائل.</p>'}catch(e){document.getElementById('smsList').textContent=e.message}};select.onchange=load;await load();
}
async function absherPage(skipCharge=false){
 if(!me){location.hash='#/login';return}
 const lines=(await api('/telecom/lines')).lines.filter(l=>l.status==='active'&&l.data_remaining_mb>0&&l.expires_at&&new Date(l.expires_at.replace(' ','T')+'Z')>new Date());
 const selected=sessionStorage.getItem('saliyah_absher_line');
 if(!selected||!lines.some(l=>l.id===selected)){
 page('أبشر الصالية — اتصال الإنترنت',`<div class="notice">الدخول إلى أبشر الصالية يستهلك 1 ميجابايت من باقة الإنترنت الصالية لكل فتح أو عملية. لا تُستهلك بيانات شركة اتصال حقيقية.</div><form class="card form" id="absherConnect"><label class="field">اختر شريحة الإنترنت<select class="input" name="line_id">${lines.map(l=>`<option value="${safe(l.id)}">${safe(l.number)} — المتبقي ${l.data_remaining_mb} ميجابايت</option>`).join('')}</select></label><button class="btn gold" ${lines.length?'':'disabled'}>اتصال بأبشر الصالية</button><p role="status"></p></form><a href="#/telecom">شراء باقة إنترنت</a>`);
 document.getElementById('absherConnect').onsubmit=async e=>{e.preventDefault();try{const line_id=new FormData(e.target).get('line_id');await post('/absher/access',{line_id});sessionStorage.setItem('saliyah_absher_line',line_id);await absherPage(true)}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};return;
 }
 if(!skipCharge){try{await post('/absher/access',{line_id:selected})}catch(e){sessionStorage.removeItem('saliyah_absher_line');alert(e.message);return await absherPage()}}
 const r=await api('/absher/overview');const labels={identity:'الهوية الوطنية',passport:'الجوازات',residency:'الإقامة',vehicle_registration:'تسجيل مركبة',vehicle_transfer:'نقل ملكية مركبة',driving_license:'رخصة القيادة',weapon_registration:'طلب تسجيل سلاح',weapon_renewal:'تجديد تسجيل سلاح',travel_permission:'تصريح سفر',civil_record:'السجل المدني',other:'خدمة وطنية أخرى'};
 let admin=null;if(me.role==='king'||me.role==='employee')try{admin=await api('/absher/admin')}catch{}
 page('أبشر الصالية — الخدمات الوطنية',`<div class="notice">بوابة رسمية داخل عالم المملكة الصالية الافتراضي فقط. تسجيل المركبات والأسلحة هنا لا يمثل تسجيلًا حكوميًا حقيقيًا أو تصريحًا بحمل سلاح. الطلبات تخضع للمراجعة.</div>
 <div class="grid"><form class="card form" id="absherAsset"><h3>تسجيل مركبة أو سلاح للمراجعة</h3><label class="field">النوع<select class="input" name="kind"><option value="vehicle">مركبة</option><option value="weapon">سلاح</option></select></label><label class="field">الاسم أو الوصف<input class="input" name="name" minlength="2" maxlength="100" required></label><label class="field">رقم اللوحة أو الرقم التسلسلي<input class="input" name="identifier" minlength="3" maxlength="50" required></label><label class="field">ملاحظات<textarea class="input" name="notes" maxlength="500"></textarea></label><button class="btn gold">تقديم طلب تسجيل</button><p role="status"></p></form>
 <form class="card form" id="absherService"><h3>طلب خدمة وطنية</h3><label class="field">الخدمة<select class="input" name="service">${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="field">تفاصيل الطلب<textarea class="input" name="details" minlength="5" maxlength="1000" required></textarea></label><button class="btn gold">تقديم الطلب</button><p role="status"></p></form></div>
 <h2>مركباتي وأسلحتي المسجلة في النظام</h2>${r.assets.map(x=>`<div class="card"><b>${x.kind==='vehicle'?'مركبة':'سلاح'} — ${safe(x.name)}</b><p>الرقم: ${safe(x.identifier)} · الحالة: ${safe(x.status)}</p></div>`).join('')||'<p class="empty">لا توجد سجلات.</p>'}
 <h2>طلباتي الوطنية</h2>${r.requests.map(x=>`<div class="card"><b>${safe(labels[x.service]||x.service)}</b><p>${safe(x.details)}</p><p>الحالة: ${safe(x.status)} · ${safe(x.created_at)}</p></div>`).join('')||'<p class="empty">لا توجد طلبات.</p>'}
 ${admin?`<h2>مراجعة الطلبات الوطنية</h2>${[...admin.assets.map(x=>({...x,record_kind:'asset'})),...admin.requests.map(x=>({...x,record_kind:'request'}))].map(x=>`<div class="card"><b>${safe(x.username)} — ${safe(x.name||labels[x.service]||x.service)}</b><p>${safe(x.identifier||x.details||'')}</p><div class="actions"><button class="btn absherDecision" data-id="${safe(x.id)}" data-kind="${x.record_kind}" data-decision="approved">اعتماد</button><button class="btn outline absherDecision" data-id="${safe(x.id)}" data-kind="${x.record_kind}" data-decision="rejected">رفض</button></div></div>`).join('')||'<p class="empty">لا توجد طلبات بانتظار المراجعة.</p>'}`:''}`);
 for(const [id,path] of [['absherAsset','/absher/asset'],['absherService','/absher/request']])document.getElementById(id).onsubmit=async e=>{e.preventDefault();try{await post('/absher/access',{line_id:selected});await post(path,Object.fromEntries(new FormData(e.target)));await absherPage(true)}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};
 for(const b of document.querySelectorAll('.absherDecision'))b.onclick=async()=>{if(!confirm('تأكيد القرار؟'))return;try{await post('/absher/access',{line_id:selected});await post('/absher/decision',{id:b.dataset.id,kind:b.dataset.kind,decision:b.dataset.decision});await absherPage(true)}catch(e){alert(e.message)}};
}
async function bordersPage(){if(!me){location.hash='#/login';return}const [posts,moves,customs]=await Promise.all([api('/borders/posts'),api('/borders/movements'),api('/borders/customs')]);const options=posts.posts.map(p=>`<option value="${safe(p.id)}">${safe(p.name)}</option>`).join('');page('المنافذ الحدودية والجمارك',`<div class="notice">هذا نظام حدود وجمارك داخلي للمملكة الصالية فقط. العبور لا يُسجّل إلا لوثيقة مسجلة وصالحة ودون تعميم نشط.</div><div class="grid">${posts.posts.map(p=>`<div class="card"><h3>${safe(p.name)}</h3><p class="muted">${safe(p.profile)}</p></div>`).join('')}</div><div class="grid"><form class="card form" id="borderCheck"><h3>فحص وثيقة السفر</h3><label class="field">رقم الوثيقة<input class="input" name="number" required></label><button class="btn">فحص</button><p role="status"></p></form><form class="card form" id="borderMovement"><h3>تسجيل عبور</h3><label class="field">المنفذ<select class="input" name="post_id">${options}</select></label><label class="field">رقم الوثيقة<input class="input" name="number" required></label><label class="field">الحركة<select class="input" name="direction"><option value="entry">دخول</option><option value="exit">خروج</option></select></label><label class="field">سبب العبور<input class="input" name="purpose" required maxlength="250"></label><button class="btn gold">تسجيل الحركة</button><p role="status"></p></form><form class="card form" id="customsNew"><h3>إقرار جمركي</h3><label class="field">المنفذ<select class="input" name="post_id">${options}</select></label><label class="field">وصف البضاعة<input class="input" name="description" maxlength="500" required></label><label class="field">الكمية<input class="input" name="quantity" type="number" min="1" max="1000000" required></label><button class="btn">تسجيل الإقرار</button><p role="status"></p></form></div><h2>آخر حركات العبور</h2>${moves.movements.map(m=>`<div class="card"><b>${m.direction==='entry'?'دخول':'خروج'} — ${safe(m.full_name)}</b><p class="muted">${safe(m.post)} · ${safe(m.created_at)} · ${safe(m.number)}</p><p>${safe(m.purpose)}</p></div>`).join('')||'<div class="empty">لا توجد حركات مسجلة.</div>'}<h2>الإقرارات الجمركية</h2>${customs.declarations.map(c=>`<div class="card"><b>${safe(c.description)}</b><p class="muted">${safe(c.post)} · الكمية ${c.quantity} · ${safe(c.created_at)}</p><label class="field">الحالة<select class="input customs-status" data-id="${safe(c.id)}"><option value="submitted" ${c.status==='submitted'?'selected':''}>مقدم</option><option value="inspecting" ${c.status==='inspecting'?'selected':''}>تحت الفحص</option><option value="cleared" ${c.status==='cleared'?'selected':''}>مفسوح</option><option value="held" ${c.status==='held'?'selected':''}>محتجز</option></select></label></div>`).join('')||'<div class="empty">لا توجد إقرارات.</div>'}`);for(const [id,url] of [['borderCheck','/borders/check'],['borderMovement','/borders/movement'],['customsNew','/borders/customs']])document.getElementById(id).onsubmit=async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f));if(id==='customsNew')b.quantity=Number(b.quantity);try{const r=await post(url,b);if(id==='borderCheck'){f.querySelector('[role=status]').textContent=`نتيجة الفحص: ${r.result} · ${r.document?.full_name||'غير مسجل'} · المرجع ${r.check_id}`}else await bordersPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};document.querySelectorAll('.customs-status').forEach(el=>el.onchange=async()=>{try{await post('/borders/customs/status',{id:el.dataset.id,status:el.value})}catch(e){alert(e.message);await bordersPage()}})}

async function educationPage(){if(!me){location.hash='#/login';return}const [inst,apps,trans]=await Promise.all([api('/education/institutions'),api('/education/applications'),api('/education/transcript')]);const levels={primary:'ابتدائي',middle:'متوسط',secondary:'ثانوي',university:'جامعة'};const status={submitted:'قيد المراجعة',accepted:'مقبول',rejected:'مرفوض'};
page('التعليم في المملكة الصالية',`<div class="notice">المدارس والجامعات تُضاف من إدارة المملكة، ولا تُفرض رسوم فعلية حاليًا. قبول الطلب لا يعني خصم رسوم أو إصدار شهادة تلقائيًا.</div>${inst.can_manage?`<form class="card form" id="schoolNew"><h3>إضافة مدرسة أو جامعة</h3><label class="field">الاسم<input class="input" name="name" required maxlength="120"></label><label class="field">المرحلة<select class="input" name="level">${Object.entries(levels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="field">القطاع<select class="input" name="sector"><option value="public">حكومي</option><option value="private">خاص</option></select></label><label class="field">السعة<input class="input" type="number" name="capacity" min="1" required></label><label class="field">أقل درجة للقبول<input class="input" type="number" name="min_grade" min="0" max="100" value="55" required></label><label class="field">الرسوم الصالية (0 للحكومي)<input class="input" type="number" name="fee" min="0" value="0" required></label><button class="btn gold">إضافة المؤسسة</button><p role="status"></p></form>`:''}<h2>المدارس والجامعات</h2><div class="grid">${inst.institutions.map(i=>`<div class="card"><h3>${safe(i.name)}</h3><p class="muted">${levels[i.level]} · ${i.sector==='public'?'حكومي':'خاص'} · المقاعد ${i.capacity} · الحد الأدنى ${i.min_grade}</p><p>الرسوم: ${i.fee} ريال صالي</p><form class="form schoolApply" data-id="${safe(i.id)}"><label class="field">الدرجة السابقة (للابتدائي يمكن تركها فارغة)<input class="input" name="previous_grade" type="number" min="0" max="100" step="0.01"></label><button class="btn">تقديم طلب</button><p role="status"></p></form></div>`).join('')||'<div class="empty">لم تُضف مؤسسات تعليمية بعد.</div>'}</div><h2>طلبات القبول</h2>${apps.applications.map(x=>`<div class="card"><b>${safe(x.institution_name)}</b><p class="muted">${status[x.status]} · ${safe(x.created_at)}</p>${inst.can_manage&&x.status==='submitted'?`<button class="btn reviewEdu" data-id="${safe(x.id)}" data-status="accepted">قبول</button> <button class="btn reviewEdu" data-id="${safe(x.id)}" data-status="rejected">رفض</button>`:''}${inst.can_manage&&x.status==='accepted'?`<form class="form gradeEdu" data-id="${safe(x.id)}"><label class="field">الدرجة<input class="input" type="number" name="grade" min="0" max="100" step="0.01" required></label><label><input type="checkbox" name="retest"> اختبار إعادة</label><button class="btn">حفظ الدرجة</button><p role="status"></p></form>`:''}</div>`).join('')||'<div class="empty">لا توجد طلبات.</div>'}<h2>السجل الدراسي</h2>${trans.grades.map(x=>`<div class="card"><b>${safe(x.institution_name)}</b><p>الدرجة النهائية: ${x.final_grade} / 100 ${x.retest_grade!==null?'(بعد الإعادة)':''}</p><small>${safe(x.updated_at)}</small></div>`).join('')||'<div class="empty">لا توجد درجات مسجلة.</div>'}`);
const f=document.getElementById('schoolNew');if(f)f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f));for(const k of ['capacity','min_grade','fee'])b[k]=Number(b[k]);try{await post('/education/institutions',b);await educationPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};
document.querySelectorAll('.schoolApply').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const v=new FormData(f).get('previous_grade');try{await post('/education/apply',{institution_id:f.dataset.id,previous_grade:v===''?null:Number(v)});await educationPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}});
document.querySelectorAll('.reviewEdu').forEach(b=>b.onclick=async()=>{try{await post('/education/review',{id:b.dataset.id,status:b.dataset.status});await educationPage()}catch(err){alert(err.message)}});
document.querySelectorAll('.gradeEdu').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f);try{await post('/education/grade',{application_id:f.dataset.id,grade:Number(d.get('grade')),retest:d.has('retest')});await educationPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}});
}

async function payrollPage(){if(!me){location.hash='#/login';return}const mine=await api('/payroll/mine');const admin=me.role==='king'?await api('/payroll/admin'):null;
page('الرواتب وميزانيات جهات العمل',`<div class="notice">جميع المبالغ بالريال الصالي داخل المحاكاة. الصرف يدوي لكل عقد وشهر، ولا يُكرر راتب الشهر نفسه.</div><h2>عقودي ورواتبي</h2>${mine.contracts.map(c=>`<div class="card"><b>${safe(c.title)} — ${safe(c.employer)}</b><p>${c.salary} ريال صالي شهريًا · ${c.active?'نشط':'موقوف'}</p></div>`).join('')||'<p class="empty">لا توجد عقود بعد.</p>'}${mine.payments.map(p=>`<div class="card">راتب ${safe(p.period)} · ${p.amount} ريال صالي · ${safe(p.employer)}</div>`).join('')||'<p class="muted">لا توجد رواتب مصروفة.</p>'}${admin?`<h2>ميزانيات الجهات</h2>${admin.budgets.map(b=>`<div class="card"><b>${safe(b.employer)}</b> · ${b.balance} ريال صالي<form class="form fundBudget" data-employer="${safe(b.employer)}"><label class="field">إضافة ميزانية<input class="input" type="number" name="amount" min="1" max="100000000" required></label><button class="btn">تمويل الجهة</button><p role="status"></p></form></div>`).join('')||'<p class="empty">أنشئ عقدًا لتظهر جهة العمل.</p>'}<h2>طلبات مقبولة تنتظر إنشاء عقد</h2>${admin.accepted.map(a=>`<div class="card"><b>${safe(a.username)} — ${safe(a.title)}</b><p>${safe(a.employer)} · ${a.salary} ريال صالي</p><button class="btn createContract" data-id="${safe(a.id)}">إنشاء عقد وظيفي</button></div>`).join('')||'<p class="empty">لا توجد طلبات مقبولة جديدة.</p>'}<h2>العقود</h2>${admin.contracts.map(c=>`<div class="card"><b>${safe(c.username)} — ${safe(c.title)}</b><p>${safe(c.employer)} · ${c.salary} ريال صالي · ${c.active?'نشط':'موقوف'}</p><button class="btn toggleContract" data-id="${safe(c.id)}" data-active="${c.active?'false':'true'}">${c.active?'إيقاف العقد':'تفعيل العقد'}</button> ${c.active?`<form class="form paySalary" data-id="${safe(c.id)}"><label class="field">شهر الراتب (YYYY-MM)<input class="input" type="month" name="period" required></label><button class="btn gold">صرف الراتب</button><p role="status"></p></form>`:''}</div>`).join('')||'<p class="empty">لا توجد عقود.</p>'}<h2>آخر الرواتب المصروفة</h2>${admin.payments.map(p=>`<div class="card">${safe(p.username)} · ${safe(p.employer)} · ${safe(p.period)} · ${p.amount} ريال صالي</div>`).join('')||'<p class="empty">لا توجد عمليات.</p>'}`:''}`);
const action=async(el,url,body)=>{try{await post(url,body);await payrollPage()}catch(e){const status=el.closest('form')?.querySelector('[role=status]');if(status)status.textContent=e.message;else alert(e.message)}};
document.querySelectorAll('.createContract').forEach(b=>b.onclick=()=>action(b,'/payroll/contract',{application_id:b.dataset.id}));document.querySelectorAll('.toggleContract').forEach(b=>b.onclick=()=>action(b,'/payroll/contract/status',{id:b.dataset.id,active:b.dataset.active==='true'}));document.querySelectorAll('.fundBudget').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(f,'/payroll/fund',{employer:f.dataset.employer,amount:Number(new FormData(f).get('amount'))})});document.querySelectorAll('.paySalary').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(f,'/payroll/pay',{contract_id:f.dataset.id,period:new FormData(f).get('period')})});}

async function bankAdmin(){if(!me){location.hash='#/login';return}if(me.role!=='king'&&me.role!=='employee'){page('غير مخول','');return}const bank=new URLSearchParams(location.hash.split('?')[1]||'').get('bank')||'saliyah';const [a,h]=await Promise.all([api('/bank-admin/accounts?bank='+bank),api('/bank-admin/history?bank='+bank)]);page('إدارة أرصدة البنوك',`<div class="notice">التحكم اليدوي بأرصدة المحاكاة، بما فيها السالبة، يسجل اسم الموظف والسبب والرصيد السابق والجديد.</div><div class="actions">${[['saliyah','بنك الصالية'],['national','البنك الوطني'],['development','بنك التنمية']].map(([id,n])=>`<a class="btn outline" href="#/bank-admin?bank=${id}">${n}</a>`).join('')}</div><form id="balanceForm" class="card form"><label class="field">الحساب<select name="account_id" class="input">${a.accounts.map(x=>`<option value="${safe(x.id)}">${safe(x.username)} — ${safe(x.balance)} ريال</option>`).join('')}</select></label><label class="field">العملية<select name="mode" class="input"><option value="set">تعيين رصيد محدد (يسمح بالسالب)</option><option value="add">زيادة الرصيد</option><option value="subtract">خصم من الرصيد</option></select></label><label class="field">المبلغ<input class="input" type="number" name="amount" step="1" required></label><label class="field">سبب العملية<input class="input" name="reason" minlength="5" maxlength="300" required></label><button class="btn gold" ${a.accounts.length?'':'disabled'}>تسجيل التعديل</button><p role="status"></p></form><h2>سجل تعديلات الأرصدة</h2>${h.operations.map(x=>`<div class="card"><b>${safe(x.actor)} · ${safe(x.mode)}</b><p>من ${safe(x.previous_balance)} إلى ${safe(x.new_balance)} ريال</p><p>${safe(x.reason)}</p><small>${safe(x.created_at)}</small></div>`).join('')||'<p class="empty">لا توجد عمليات.</p>'}`);document.querySelector('#balanceForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.amount=Number(b.amount);try{await post('/bank-admin/adjust',b);await bankAdmin()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}}}
async function installmentsPage(){if(!me){location.hash='#/login';return}const [r,a]=await Promise.all([api('/installments/mine'),api('/banking/accounts')]);page('تابي وتمارا الصالية',`<div class="notice">نظام تقسيط داخلي بالريال الصالي، غير مرتبط بتابي أو تمارا الحقيقيتين. الحد الحالي 5000 ريال لكل خدمة.</div><form id="installForm" class="card form"><h3>إنشاء خطة تقسيط</h3><label class="field">الخدمة<select class="input" name="provider"><option value="tabby">تابي الصالية</option><option value="tamara">تمارا الصالية</option></select></label><label class="field">المتجر<input class="input" name="merchant" required minlength="2"></label><label class="field">المبلغ<input class="input" type="number" name="amount" min="4" max="1000000" step="1" required></label><button class="btn">إنشاء أربعة أقساط</button><p role="status"></p></form><h2>خطط التقسيط</h2>${r.plans.map(x=>`<div class="card"><h3>${x.provider==='tabby'?'تابي الصالية':'تمارا الصالية'} — ${safe(x.merchant)}</h3><p>${safe(x.amount)} ريال · ${safe(x.status)}</p><button class="btn outline showDues" data-id="${safe(x.id)}">عرض الأقساط</button><div id="dues-${safe(x.id)}"></div></div>`).join('')||'<p class="empty">لا توجد خطط.</p>'}`);document.querySelector('#installForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.amount=Number(b.amount);try{await post('/installments/create',b);await installmentsPage()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};document.querySelectorAll('.showDues').forEach(btn=>btn.onclick=async()=>{const r=await api('/installments/schedule?id='+encodeURIComponent(btn.dataset.id));const target=document.getElementById('dues-'+btn.dataset.id);target.innerHTML=r.dues.map(d=>`<div class="card"><b>القسط ${d.installment_number}: ${d.amount} ريال</b><p>الاستحقاق: ${safe(d.due_date)} · ${d.paid_at?'مدفوع':'غير مدفوع'}</p>${d.paid_at?'':`<form class="payDue" data-id="${safe(d.id)}"><select class="input" name="account_id">${a.accounts.map(x=>`<option value="${safe(x.id)}">${safe(x.bank)} — ${x.balance}</option>`).join('')}</select><button class="btn" ${a.accounts.length?'':'disabled'}>سداد</button><p role="status"></p></form>`}</div>`).join('');target.querySelectorAll('.payDue').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await post('/installments/pay',{due_id:f.dataset.id,account_id:new FormData(f).get('account_id')});await installmentsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}})})}
async function stateBudgetsPage(){if(!me){location.hash='#/login';return}const r=await api('/state-budgets/list');const labels={submitted:'بانتظار مراجعة المالية',finance_approved:'موافقة المالية — بانتظار الملك',finance_rejected:'مرفوض من المالية',king_approved:'معتمد ملكيًا',king_rejected:'مرفوض ملكيًا'};
page('ميزانية الدولة واعتماد الجهات',`<div class="notice">هذه شاشة اعتماد مقترحات ميزانيات الوزارات والمحافظات. الاعتماد لا يضيف أموالًا تلقائيًا إلى الحسابات أو ميزانيات الرواتب.</div>${r.can_propose?`<form id="stateBudgetNew" class="card form"><h3>اقتراح ميزانية</h3><label class="field">الجهة<input class="input" name="entity_name" minlength="3" maxlength="160" required></label><label class="field">نوع الجهة<select class="input" name="entity_type"><option value="ministry">وزارة</option><option value="governorate">محافظة</option></select></label><label class="field">السنة المالية<input class="input" type="number" name="fiscal_year" min="2026" max="2100" value="${new Date().getFullYear()}" required></label><label class="field">المبلغ بالريال الصالي<input class="input" type="number" name="amount" min="1" max="1000000000" required></label><label class="field">مبررات الطلب<textarea class="input" name="justification" minlength="10" maxlength="2000" required></textarea></label><button class="btn gold">رفع المقترح</button><p role="status"></p></form>`:''}<h2>سجل مقترحات الميزانيات</h2>${r.requests.map(x=>`<div class="card"><h3>${safe(x.entity_name)}</h3><p>${Number(x.amount).toLocaleString('ar-SA')} ريال صالي · ${safe(x.fiscal_year)} · ${safe(labels[x.status]||x.status)}</p><p class="muted">مقدم الطلب: ${safe(x.requester)} · ${safe(x.created_at)}</p><p>${safe(x.justification)}</p>${x.finance_note?`<p>ملاحظة المالية: ${safe(x.finance_note)}</p>`:''}${x.king_note?`<p>القرار الملكي: ${safe(x.king_note)}</p>`:''}${r.can_review&&x.status==='submitted'?`<form class="form financeReview" data-id="${safe(x.id)}"><label class="field">ملاحظة المراجعة<input class="input" name="note" minlength="3" maxlength="1000" required></label><button class="btn" name="status" value="finance_approved">موافقة المالية</button> <button class="btn outline" name="status" value="finance_rejected">رفض المالية</button><p role="status"></p></form>`:''}${r.can_approve&&x.status==='finance_approved'?`<form class="form royalReview" data-id="${safe(x.id)}"><label class="field">ملاحظة القرار<input class="input" name="note" minlength="3" maxlength="1000" required></label><button class="btn gold" name="status" value="king_approved">اعتماد ملكي</button> <button class="btn outline" name="status" value="king_rejected">رفض ملكي</button><p role="status"></p></form>`:''}<button class="btn outline budgetEvents" data-id="${safe(x.id)}">سجل القرارات</button><div id="events-${safe(x.id)}"></div></div>`).join('')||'<p class="empty">لا توجد مقترحات حتى الآن.</p>'}`);
const f=document.getElementById('stateBudgetNew');if(f)f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f));b.amount=Number(b.amount);b.fiscal_year=Number(b.fiscal_year);try{await post('/state-budgets/propose',b);await stateBudgetsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};
for(const [cls,url] of [['financeReview','/state-budgets/review'],['royalReview','/state-budgets/royal-decision']])document.querySelectorAll('.'+cls).forEach(f=>f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f));b.id=f.dataset.id;b.status=e.submitter.value;try{await post(url,b);await stateBudgetsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}});
document.querySelectorAll('.budgetEvents').forEach(b=>b.onclick=async()=>{try{const r=await api('/state-budgets/events?id='+encodeURIComponent(b.dataset.id));document.getElementById('events-'+b.dataset.id).innerHTML=r.events.map(x=>`<p class="muted">${safe(x.created_at)} · ${safe(x.actor)} · ${safe(labels[x.new_status]||x.new_status)} · ${safe(x.note)}</p>`).join('')}catch(e){alert(e.message)}})}


async function courtsPage(){if(!me){location.hash='#/login';return}const r=await api('/courts/list');const labels={filed:'مرفوعة',review:'قيد المراجعة',scheduled:'مجدولة',heard:'نُظرت',judged:'صدر حكم',closed:'مغلقة'};
page('القضاء والمحاماة',`<p><a class="btn outline" href="#/justice16">الشرطة والبلاغات والاستئناف</a> <a class="btn outline" href="#/justice17">النيابة والأدلة وتنفيذ الأحكام</a> <a class="btn outline" href="#/justice18">مذكرات القضايا</a> <a class="btn outline" href="#/justice19">محاضر الجلسات</a> <a class="btn outline" href="#/justice20">تصحيحات المحاضر</a> <a class="btn outline" href="#/justice21">مرفقات القضايا</a> <a class="btn outline" href="#/justice23">دوائر الاستئناف والنقض</a> <a class="btn outline" href="#/justice24">أوامر تنفيذ الأحكام</a></p><div class="notice">نظام قضايا داخلي للمملكة الصالية؛ لا يمثل محكمة أو ترخيص محاماة حقيقيًا.</div><form id="courtFile" class="card form"><h3>رفع قضية جديدة</h3><label class="field">نوع القضية<select class="input" name="kind"><option value="civil">مدنية</option><option value="commercial">تجارية</option><option value="administrative">إدارية</option><option value="family">أحوال شخصية</option><option value="criminal">جزائية</option></select></label><label class="field">عنوان القضية<input class="input" name="title" required minlength="5" maxlength="160"></label><label class="field">اسم المدعى عليه<input class="input" name="defendant_name" required minlength="2" maxlength="160"></label><label class="field">اسم مستخدم المدعى عليه (اختياري لربط حسابه)<input class="input" name="defendant_username"></label><label class="field">وقائع الدعوى<textarea class="input" name="statement" required minlength="10" maxlength="5000"></textarea></label><button class="btn gold">تسجيل القضية</button><p role="status"></p></form>
${r.my_lawyer?`<div class="card">حالة طلب المحاماة: <b>${safe(r.my_lawyer.status)}</b></div>`:`<form id="lawyerApply" class="card form"><h3>طلب تسجيل محامٍ</h3><label class="field">الاسم المهني<input class="input" name="display_name" required minlength="3"></label><label class="field">رقم الترخيص الداخلي<input class="input" name="license_number" required minlength="4"></label><button class="btn">إرسال طلب الاعتماد</button><p role="status"></p></form>`}
<h2>القضايا المسجلة لك</h2>${r.cases.map(c=>`<div class="card"><b>${safe(c.reference)} — ${safe(c.title)}</b><p>${safe(labels[c.status]||c.status)} · ${safe(c.created_at)}</p><button class="btn outline caseDetail" data-id="${safe(c.id)}">فتح ملف القضية</button><div id="case-${safe(c.id)}"></div></div>`).join('')||'<p class="empty">لا توجد قضايا.</p>'}<h2>طلبات التوكيل الواردة</h2><div id="counselInvites"></div>${r.can_manage?'<h2>اعتماد المحامين</h2><div id="lawyerPending"></div>':''}`);
const f=document.querySelector('#courtFile');f.onsubmit=async e=>{e.preventDefault();try{const x=await post('/courts/file',Object.fromEntries(new FormData(f)));alert('تم تسجيل القضية: '+x.reference);await courtsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};
const apply=document.querySelector('#lawyerApply');if(apply)apply.onsubmit=async e=>{e.preventDefault();try{await post('/courts/lawyer/apply',Object.fromEntries(new FormData(apply)));await courtsPage()}catch(err){apply.querySelector('[role=status]').textContent=err.message}};
const inv=await api('/courts/counsel/invitations');document.querySelector('#counselInvites').innerHTML=inv.invitations.map(x=>`<form class="card invite" data-case="${safe(x.case_id)}" data-client="${safe(x.client_id)}"><b>${safe(x.reference)} — ${safe(x.title)}</b><div class="actions"><button class="btn" name="status" value="accepted">قبول التوكيل</button><button class="btn outline" name="status" value="rejected">رفض</button></div><p role="status"></p></form>`).join('')||'<p class="muted">لا توجد طلبات.</p>';
document.querySelectorAll('.invite').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await post('/courts/counsel/respond',{case_id:f.dataset.case,client_id:f.dataset.client,status:e.submitter.value});await courtsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}});
if(r.can_manage){const pending=await api('/courts/lawyer/pending');document.querySelector('#lawyerPending').innerHTML=pending.lawyers.map(l=>`<form class="card approveLawyer" data-id="${safe(l.user_id)}"><b>${safe(l.display_name)} · ${safe(l.license_number)}</b><button class="btn" name="status" value="active">اعتماد</button><button class="btn outline" name="status" value="suspended">رفض/تعليق</button><p role="status"></p></form>`).join('')||'<p class="muted">لا توجد طلبات.</p>';document.querySelectorAll('.approveLawyer').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await post('/courts/lawyer/approve',{user_id:f.dataset.id,status:e.submitter.value});await courtsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}})}
document.querySelectorAll('.caseDetail').forEach(b=>b.onclick=async()=>{const d=await api('/courts/detail?id='+encodeURIComponent(b.dataset.id)),c=d.case,t=document.getElementById('case-'+b.dataset.id);t.innerHTML=`<div class="notice"><b>الوقائع</b><p>${safe(c.statement)}</p>${c.judgment?`<b>الحكم</b><p>${safe(c.judgment)}</p>`:''}</div><p><a class="btn outline" href="#/justice18/${safe(c.id)}">مذكرات القضية والمرافعات</a> <a class="btn outline" href="#/justice19/${safe(c.id)}">محاضر الجلسات</a> <a class="btn outline" href="#/justice20/${safe(c.id)}">ملحقات المحاضر</a> <a class="btn outline" href="#/justice21/${safe(c.id)}">مرفقات القضية</a></p><h3>الجلسات</h3>${d.hearings.map(h=>`<p>${safe(h.starts_at)} · ${safe(h.location)} · ${safe(h.notes)}</p>`).join('')||'<p>لا توجد جلسات.</p>'}<h3>المحامون</h3>${d.counsel.map(x=>`<p>${safe(x.display_name)} · ${safe(x.status)}</p>`).join('')||'<p>لا يوجد توكيل.</p>'}${d.is_party?`<form class="form counselRequest"><label class="field">طلب توكيل محامٍ<select class="input" name="lawyer_id">${r.lawyers.map(x=>`<option value="${safe(x.user_id)}">${safe(x.display_name)}</option>`).join('')}</select></label><button class="btn" ${r.lawyers.length?'':'disabled'}>إرسال طلب التوكيل</button><p role="status"></p></form>`:''}${d.can_manage?`<form class="form courtHearing"><h3>تحديد جلسة</h3><label class="field">التاريخ والوقت<input class="input" type="datetime-local" name="starts_at" required></label><label class="field">المكان<input class="input" name="location" required minlength="3"></label><label class="field">ملاحظات<input class="input" name="notes"></label><button class="btn">إضافة الجلسة</button><p role="status"></p></form><form class="form courtManage"><h3>قرار المحكمة</h3><label class="field">الحالة<select class="input" name="status">${Object.entries(labels).filter(([k])=>k!=='filed').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="field">ملاحظة القرار<textarea class="input" name="note" required minlength="3"></textarea></label><label class="field">نص الحكم (مطلوب عند اختيار صدر حكم)<textarea class="input" name="judgment"></textarea></label><button class="btn gold">حفظ القرار</button><p role="status"></p></form>`:''}<h3>سجل القضية</h3>${d.events.map(x=>`<p class="muted">${safe(x.created_at)} · ${safe(x.event_type)} · ${safe(x.details)}</p>`).join('')}`;
for(const [selector,url] of [['.counselRequest','/courts/counsel/request'],['.courtHearing','/courts/hearing'],['.courtManage','/courts/manage']]){const f=t.querySelector(selector);if(f)f.onsubmit=async e=>{e.preventDefault();try{await post(url,{...Object.fromEntries(new FormData(f)),case_id:b.dataset.id});await courtsPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}}}})}

async function justice16Page(){if(!me){location.hash='#/login';return}const [reports,appeals]=await Promise.all([api('/justice16/reports'),api('/justice16/appeals')]);
page('الشرطة والاستئناف',`<div class="notice">جميع البلاغات والاستئنافات داخل المملكة الصالية فقط.</div><form id="policeFile" class="card form"><h3>تسجيل بلاغ</h3><label class="field">النوع<select class="input" name="kind"><option value="security">أمني</option><option value="traffic">مروري</option><option value="fraud">احتيال</option><option value="other">أخرى</option></select></label><label class="field">العنوان<input class="input" name="title" required minlength="5" maxlength="150"></label><label class="field">التفاصيل<textarea class="input" name="details" required minlength="10" maxlength="4000"></textarea></label><button class="btn gold">تسجيل البلاغ</button><p role="status"></p></form><h2>البلاغات</h2>${reports.reports.map(x=>`<div class="card"><b>${safe(x.reference)} · ${safe(x.title)}</b><p>${safe(x.status)} · ${safe(x.created_at)}</p>${reports.can_manage?`<form class="form policeUpdate" data-id="${safe(x.id)}"><select class="input" name="status"><option value="review">مراجعة</option><option value="investigating">تحقيق</option><option value="referred">إحالة</option><option value="closed">إغلاق</option></select><input class="input" name="note" placeholder="ملاحظة الإجراء" required minlength="3"><button class="btn">حفظ</button><p role="status"></p></form>`:''}</div>`).join('')||'<p class="muted">لا توجد بلاغات.</p>'}<h2>استئناف الأحكام</h2><form id="appealFile" class="card form"><label class="field">معرّف القضية (من ملف القضية)<input class="input" name="case_id" required></label><label class="field">أسباب الاستئناف<textarea class="input" name="reason" required minlength="10"></textarea></label><button class="btn">تقديم الاستئناف</button><p role="status"></p></form>${appeals.appeals.map(x=>`<div class="card"><b>${safe(x.reference)} — ${safe(x.status)}</b><p>${safe(x.reason)}</p>${appeals.can_manage?`<form class="form appealReview" data-id="${safe(x.id)}"><select class="input" name="status"><option value="accepted">قبول النظر</option><option value="rejected">رفض</option><option value="decided">فصل في الاستئناف</option></select><textarea class="input" name="note" required minlength="5" placeholder="تسبيب القرار"></textarea><button class="btn">اعتماد الإجراء</button><p role="status"></p></form>`:''}</div>`).join('')||'<p class="muted">لا توجد استئنافات.</p>'}`);
for(const [sel,url,id] of [['#policeFile','/justice16/reports',false],['#appealFile','/justice16/appeals',false],['.policeUpdate','/justice16/reports/update',true],['.appealReview','/justice16/appeals/review',true]])document.querySelectorAll(sel).forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(f));if(id)b.id=f.dataset.id;const r=await post(url,b);if(r.reference)alert('رقم البلاغ: '+r.reference);await justice16Page()}catch(err){f.querySelector('[role=status]').textContent=err.message}})}

async function justice17Page(){if(!me){location.hash='#/login';return}const [ex,ref]=await Promise.all([api('/justice17/executions'),api('/justice17/referrals').catch(()=>({referrals:[],judge:false,officer:false}))]);
page('النيابة والأدلة وتنفيذ الأحكام',`<div class="notice">سجلات قضائية داخلية للمملكة الصالية. الأدلة هنا أوصاف نصية، وليست مرفقات موثقة.</div><h2>ملفات التنفيذ</h2><p><a class="btn outline" href="#/justice24">إدارة التنفيذ عبر الأوامر القضائية</a></p>${ex.executions.map(x=>`<div class="card"><b>${safe(x.reference)} — ${safe(x.status)}</b><p>${safe(x.instructions)}</p><p class="muted">${safe(x.last_note||'')}</p>${false?`<form class="form executionUpdate" data-id="${safe(x.id)}"><select class="input" name="status"><option value="in_progress">جار التنفيذ</option><option value="suspended">معلق</option><option value="completed">مكتمل</option></select><textarea class="input" name="note" required minlength="5" placeholder="ملاحظات التنفيذ"></textarea><button class="btn">تحديث</button><p role="status"></p></form>`:''}</div>`).join('')||'<p>لا توجد ملفات تنفيذ.</p>'}${ex.can_manage?`<form id="executionOpen" class="card form"><h3>فتح ملف تنفيذ حكم</h3><input class="input" name="case_id" placeholder="معرف القضية المحكوم فيها" required><textarea class="input" name="instructions" placeholder="تعليمات التنفيذ" minlength="10" required></textarea><button class="btn gold">فتح الملف</button><p role="status"></p></form>`:''}<h2>فهرس الأدلة</h2><form id="evidenceSearch" class="card form"><input class="input" name="case_id" placeholder="معرف القضية" required><button class="btn">عرض الأدلة</button><p role="status"></p><div id="evidenceList"></div></form><form id="evidenceAdd" class="card form"><h3>إضافة وصف دليل لقضية تملك حق الاطلاع عليها</h3><input class="input" name="case_id" placeholder="معرف القضية" required><input class="input" name="title" placeholder="عنوان الدليل" minlength="3" required><textarea class="input" name="description" placeholder="وصف الدليل (لا تضع معلومات حساسة حقيقية)" minlength="10" required></textarea><button class="btn">تسجيل الوصف</button><p role="status"></p></form>${ref.judge||ref.officer?`<h2>إحالات النيابة</h2>${ref.referrals.map(x=>`<div class="card"><b>${safe(x.report_reference)} — ${safe(x.status)}</b><p>${safe(x.summary)}</p>${ref.judge&&['referred','reviewing'].includes(x.status)?`<form class="form referralReview" data-id="${safe(x.id)}"><select class="input" name="status"><option value="reviewing">قيد المراجعة</option><option value="filed_to_court">أحيلت لقضية</option><option value="dismissed">حفظ الإحالة</option></select><input class="input" name="case_id" placeholder="معرف القضية (عند الإحالة للمحكمة)"><textarea class="input" name="note" required minlength="5" placeholder="سبب القرار"></textarea><button class="btn">حفظ</button><p role="status"></p></form>`:''}</div>`).join('')||'<p>لا توجد إحالات.</p>'}${ref.officer?`<form id="referralNew" class="card form"><h3>إحالة بلاغ للنيابة</h3><input class="input" name="report_id" placeholder="معرف البلاغ قيد التحقيق" required><textarea class="input" name="summary" required minlength="10" placeholder="ملخص الإحالة"></textarea><button class="btn">إحالة</button><p role="status"></p></form>`:''}`:''}`);
for(const [sel,url,hasId] of [['#executionOpen','/justice17/executions',false],['.executionUpdate','/justice17/executions/update',true],['#evidenceAdd','/justice17/evidence',false],['#referralNew','/justice17/referrals',false],['.referralReview','/justice17/referrals/review',true]])document.querySelectorAll(sel).forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(f));if(hasId)b.id=f.dataset.id;await post(url,b);await justice17Page()}catch(err){f.querySelector('[role=status]').textContent=err.message}});
const f=document.querySelector('#evidenceSearch');f.onsubmit=async e=>{e.preventDefault();try{const d=await api('/justice17/evidence?case_id='+encodeURIComponent(new FormData(f).get('case_id')));f.querySelector('#evidenceList').innerHTML=d.evidence.map(x=>`<div class="card"><b>${safe(x.title)}</b><p>${safe(x.description)}</p><small>${safe(x.author)} · ${safe(x.created_at)}</small></div>`).join('')||'لا توجد أدلة مسجلة.'}catch(err){f.querySelector('[role=status]').textContent=err.message}}}

