 document.querySelector('#healthBook').onsubmit=async e=>{e.preventDefault();try{await post('/health/appointments',Object.fromEntries(new FormData(e.target)));await healthPage()}catch(err){e.target.querySelector('[role=status]').textContent=err.message}};
 const f=document.querySelector('#healthClinic');if(f)f.onsubmit=async e=>{e.preventDefault();try{await post('/health/clinics',Object.fromEntries(new FormData(f)));await healthPage()}catch(err){f.querySelector('[role=status]').textContent=err.message}};
 document.querySelectorAll('.healthCancel').forEach(b=>b.onclick=async()=>{try{await post('/health/cancel',{id:b.dataset.id});await healthPage()}catch(err){alert(err.message)}});
