async function justice21Page(){
 if(!me){location.hash='#/login';return}
 page('مرفقات وأدلة القضايا',`<div class="notice">مرفقات خاصة بالمحاكاة القضائية. لا ترفع وثائق شخصية حقيقية. PDF أو JPG أو PNG أو WebP بحد 5 ميجابايت.</div><form class="card form" id="fileLookup"><label class="field">معرف القضية<input class="input" name="case_id" required minlength="10"></label><button class="btn">فتح المرفقات</button><p role="status"></p></form><div id="fileArea"></div>`);
 const f=document.querySelector('#fileLookup'),initial=location.hash.split('/')[2]||'';if(initial)f.querySelector('[name=case_id]').value=decodeURIComponent(initial);
 f.onsubmit=async e=>{e.preventDefault();const caseId=new FormData(f).get('case_id');try{const r=await api('/justice21/files?case_id='+encodeURIComponent(caseId));const area=document.querySelector('#fileArea');area.innerHTML=`<form class="card form" id="fileUpload"><h3>إضافة مستند للقضية</h3><label class="field">عنوان المستند<input class="input" name="title" minlength="3" maxlength="160" required></label><label class="field">الملف<input class="input" name="file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" required></label><button class="btn gold">رفع المستند</button><p role="status"></p></form><h3>المرفقات المسجلة</h3>${r.files.map(x=>`<div class="card"><b>${safe(x.title)}</b><p class="muted">${safe(x.filename)} · ${Math.ceil(x.byte_size/1024)} KB · ${safe(x.created_at)}</p><a class="btn outline" href="/api/justice21/download?id=${encodeURIComponent(x.id)}">تنزيل المستند</a></div>`).join('')||'<p class="empty">لا توجد مرفقات.</p>'}`;
 const upload=document.querySelector('#fileUpload');upload.onsubmit=async ev=>{ev.preventDefault();const file=upload.querySelector('[name=file]').files[0];if(!file||file.size>5242880){upload.querySelector('[role=status]').textContent='الحد الأقصى 5 ميجابايت';return}const body=new FormData(upload);try{const response=await fetch('/api/justice21/files?case_id='+encodeURIComponent(caseId),{method:'POST',body,credentials:'same-origin'});const result=await response.json();if(!response.ok)throw Error(result.error||'فشل رفع الملف');f.requestSubmit()}catch(err){upload.querySelector('[role=status]').textContent=err.message}};
 }catch(err){f.querySelector('[role=status]').textContent=err.message}};if(initial)f.requestSubmit();
}

