 page('أمان الحساب والجلسات',`<div class="notice">راقب جلسات الدخول، وألغِ أي جلسة غير معروفة. حماية تسجيل الدخول تحدّ المحاولات المتكررة على اسم المستخدم.</div><div class="actions"><button class="btn gold" id="revokeOthers">تسجيل الخروج من الأجهزة الأخرى</button></div><h2>الجلسات النشطة</h2>${r.sessions.map(x=>`<div class="card"><b>${x.current?'هذا الجهاز':'جلسة أخرى'}</b><p>بداية الجلسة: ${safe(x.created_at)} · تنتهي: ${safe(x.expires_at)}</p><button class="btn outline revokeSession" data-id="${safe(x.id)}">إنهاء الجلسة</button></div>`).join('')||'<p>لا توجد جلسات.</p>'}`);
 document.querySelector('#revokeOthers').onclick=async()=>{if(!confirm('إنهاء كل الجلسات الأخرى؟'))return;try{await post('/security/revoke-others',{});await securityPage()}catch(e){alert(e.message)}};
 document.querySelectorAll('.revokeSession').forEach(b=>b.onclick=async()=>{if(!confirm('إنهاء هذه الجلسة؟'))return;try{const r=await post('/security/revoke',{id:b.dataset.id});if(r.selfRevoked){await refreshUser();location.hash='#/login'}else await securityPage()}catch(e){alert(e.message)}});
