async function enforcementPage(){
 if(!me){location.hash='#/login';return}
 try{
 const r=await api('/enforcement/cases');
 const names={1:'الداخلية',3:'العدل',7:'المالية'};
 const statuses={pending:'بانتظار الاعتماد',approved:'معتمدة',rejected:'مرفوضة'};
 const actions={debt:'مطالبة مالية',service_suspension:'طلب إيقاف خدمات',both:'مطالبة مالية وطلب إيقاف خدمات'};
 page('المديونيات وإيقاف الخدمات',`<div class="notice">تُسجل المعاملات لأي مستخدم بالاسم أو رقم الهوية أو الإقامة أو الجواز. بعد اعتماد الملك يُفعّل إيقاف بعض الخدمات الاختيارية ويمكن رفعه بقرار مسجل. لا يوجد خصم بنكي تلقائي.</div><form id="enforcementNew" class="card form"><h3>فتح معاملة جديدة</h3><label class="field">اسم المستخدم أو رقم الوثيقة<input class="input" name="subject_identifier" placeholder="أدخل اسم المستخدم أو رقم الهوية أو الإقامة أو الجواز" required minlength="3"></label><label class="field">نوع المعاملة<select class="input" name="action" id="enforcementAction"><option value="debt">مطالبة مالية</option><option value="service_suspension">طلب إيقاف خدمات</option><option value="both">مطالبة مالية + طلب إيقاف خدمات</option></select></label><label class="field" id="enforcementAmountWrap">المبلغ بالهلل الصالي<input class="input" name="amount" type="number" min="0" max="100000000" value="0" required></label><label class="field">الوزارة المختصة<select class="input" name="ministry_id">${r.ministries.map(id=>`<option value="${id}">${names[id]}</option>`).join('')}</select></label><label class="field">السبب ورقم المعاملة<textarea class="input" name="reason" minlength="10" maxlength="500" required></textarea></label><button class="btn gold">رفع المعاملة للاعتماد</button><p role="status"></p></form><h2>المعاملات المسجلة</h2>${r.cases.map(x=>`<div class="card"><b>${safe(x.subject_username)}</b><p>${safe(x.residency_number||'')} · ${safe(actions[x.action]||'مطالبة مالية')}</p><p>المبلغ: ${safe(x.amount)} هلل صالي</p><p>${safe(x.reason)}</p><p>الحالة: ${safe(statuses[x.status]||x.status)} · الوزارة: ${safe(names[x.ministry_id]||'')}</p>${me.role==='king'&&x.status==='pending'?`<button class="btn decisionEnforcement" data-id="${safe(x.id)}" data-decision="approved">اعتماد</button> <button class="btn outline decisionEnforcement" data-id="${safe(x.id)}" data-decision="rejected">رفض</button>`:''}</div>`).join('')||'<p>لا توجد معاملات.</p>'}<h2>حالة إيقاف الخدمات</h2>${(r.suspensions||[]).map(h=>`<div class="card"><b>${safe(h.subject_username)}</b><p>${safe(h.reason)}</p><p>${h.status==='active'?'إيقاف خدمات نشط':'تم رفع الإيقاف'}</p>${me.role==='king'&&h.status==='active'?`<button class="btn liftEnforcement" data-id="${safe(h.id)}">رفع الإيقاف</button>`:''}</div>`).join('')||'<p>لا توجد إيقافات.</p>'}`);
 const form=document.querySelector('#enforcementNew'),action=form.querySelector('#enforcementAction'),amount=form.querySelector('[name=amount]');
 const sync=()=>{const suspended=action.value==='service_suspension';amount.disabled=suspended;amount.required=!suspended;if(suspended)amount.value='0';else amount.min='1'};
 action.onchange=sync;sync();
 form.onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(form));b.amount=Number(b.amount||0);b.ministry_id=Number(b.ministry_id);await post('/enforcement/cases',b);await enforcementPage()}catch(err){form.querySelector('[role=status]').textContent=err.message}};
 document.querySelectorAll('.liftEnforcement').forEach(b=>b.onclick=async()=>{const reason=prompt('سبب رفع الإيقاف (5 أحرف على الأقل)');if(!reason)return;try{await post('/enforcement/lift',{id:b.dataset.id,reason});await enforcementPage()}catch(err){alert(err.message)}});
 // Delegated handler: works even when the case cards are re-rendered.
 const decisions=document.querySelectorAll('.decisionEnforcement');
 decisions.forEach(btn=>btn.setAttribute('type','button'));
 app.onclick=async e=>{
  const btn=e.target.closest('.decisionEnforcement');
  if(!btn||!app.contains(btn)||btn.disabled)return;
  e.preventDefault();
  const id=btn.dataset.id,decision=btn.dataset.decision;
  const card=btn.closest('.card');
  let status=card.querySelector('.enforcementDecisionStatus');
  if(!status){status=document.createElement('p');status.className='enforcementDecisionStatus';status.setAttribute('role','status');card.appendChild(status)}
  status.textContent='جارٍ '+(decision==='approved'?'اعتماد':'رفض')+' المعاملة...';
  const buttons=card.querySelectorAll('.decisionEnforcement');
  buttons.forEach(x=>x.disabled=true);
  try{
   const result=await post('/enforcement/decision',{id,decision});
   status.textContent='تم '+(result.status==='approved'?'اعتماد':'رفض')+' المعاملة بنجاح.';
   await enforcementPage();
  }catch(err){
   status.textContent='فشل تنفيذ القرار: '+err.message;
   status.style.color='#b42318';
   buttons.forEach(x=>x.disabled=false);
  }
 };

 }catch(err){page('المديونيات وإيقاف الخدمات','<div class="notice">'+safe(err.message)+'</div>')}
}

async function xSaliyah(){
 try{
  const r=await api('/x/feed');const own=r.profile;app.onclick=null;
  let earnings=null,bankAccounts=[];
  if(own){try{earnings=await api('/x/earnings');if(earnings.eligible&&!earnings.paid){const b=await api('/banking/accounts');bankAccounts=b.accounts||[]}}catch{}}
  let ministryOptions='';
  if(me&&!own){try{const m=await api('/x/ministries');ministryOptions=m.ministries.map(x=>'<option value="'+x.id+'">'+safe(x.name)+'</option>').join('')}catch{}}
  page('𝕏 إكس الصالية',`
  <div class="notice">منصة تواصل داخل المملكة العربية الصالية. الحسابات الحكومية الموثقة تحمل علامة ✓. حساب ChatGPT الصالي حساب بوت تعريفي، وليس جهة حكومية، ولا يرد تلقائياً.</div>
  ${!me?'<div class="card">سجّل الدخول لإنشاء حساب أو التفاعل. <a href="#/login">تسجيل الدخول</a></div>':!own?`<form id="xRegister" class="card form"><h3>إنشاء حساب إكس الصالية</h3><label>نوع الحساب<select class="input" name="ministry_id"><option value="">حساب شخصي</option>${ministryOptions}</select></label><label>اسم المستخدم (إنجليزي)<input class="input" name="handle" minlength="3" maxlength="24" placeholder="ziad701"></label><label>الاسم الظاهر<input class="input" name="display_name" maxlength="60" placeholder="الاسم الظاهر"></label><button class="btn gold">إنشاء الحساب</button><p class="muted">الحساب الوزاري يُنشأ فقط بصلاحية رسمية ويوثّق تلقائياً.</p></form>`:`<div class="card"><strong>${safe(own.display_name)} ${own.kind==='bot'?'🤖':own.verified?'✓':''}</strong> <span class="muted" dir="ltr">@${safe(own.handle)}</span></div><form id="xCompose" class="card form"><h3>منشور جديد</h3><textarea class="input" name="body" maxlength="500" required placeholder="وش الجديد؟"></textarea><button class="btn gold">نشر</button></form>`}
  ${earnings?`<section class="card"><h3>⭐ برنامج شهرة الصالية</h3><p>متابعون: <b>${earnings.stats.followers}</b> / 10 · إعجابات من الآخرين: <b>${earnings.stats.likes}</b> / 20 · معيدو نشر مختلفون: <b>${earnings.stats.reposts}</b> / 5</p><p>المكافأة الشهرية الحالية: <strong>${earnings.amount} ريال صالي افتراضي</strong> (الحد الأقصى 500 ريال صالي).</p><p class="muted">تُحسب مرة واحدة كل شهر ميلادي، ولا تُحتسب تفاعلاتك مع منشوراتك. الحسابات الحكومية والبوتات غير مؤهلة.</p>${earnings.kind!=='person'?'<p>هذا الحساب غير مؤهل للأرباح.</p>':earnings.paid?'<p>✓ تم صرف مكافأة هذا الشهر.</p>':earnings.eligible?`<form id="xClaim"><label>الحساب البنكي لاستلام الأرباح<select class="input" name="bank_account_id" required>${bankAccounts.map(a=>`<option value="${safe(a.id)}">${safe(a.bank)} · ${safe(a.balance)} ريال</option>`).join('')}</select></label><button class="btn gold" ${bankAccounts.length?'':'disabled'}>صرف الأرباح</button></form>`:'<p>اجمع التفاعلات المطلوبة لفتح الأرباح.</p>'}</section>`:''}
  <h2>آخر المنشورات</h2><div id="xFeed">${r.posts.length?r.posts.map(p=>`<article class="card" style="margin-bottom:12px"><strong>${safe(p.display_name)} ${p.kind==='bot'?'🤖':p.verified?'✓':''}</strong> <span class="muted" dir="ltr">@${safe(p.handle)}</span> <small class="muted">${safe(p.created_at)}</small><p style="white-space:pre-wrap;overflow-wrap:anywhere">${safe(p.body)}</p>${p.reply_to?'<small class="muted">رد على منشور</small>':''}${p.repost_of?'<small class="muted">إعادة نشر</small>':''}<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn xLike" data-id="${safe(p.id)}">♡ ${p.likes}</button><button class="btn xReply" data-id="${safe(p.id)}">رد ${p.replies}</button><button class="btn xRepost" data-id="${safe(p.id)}">إعادة نشر</button><button class="btn xFollow" data-handle="${safe(p.handle)}">متابعة</button></div></article>`).join(''):'<div class="card">ما فيه منشورات حتى الآن. كن أول من ينشر!</div>'}</div>`);
  const claim=document.querySelector('#xClaim');if(claim)claim.onsubmit=async e=>{e.preventDefault();const btn=claim.querySelector('button');btn.disabled=true;try{const r=await post('/x/earnings/claim',{bank_account_id:new FormData(claim).get('bank_account_id')});alert('تم إيداع '+r.amount+' ريال صالي في حسابك');await xSaliyah()}catch(err){alert(err.message);btn.disabled=false}};
  const reg=document.querySelector('#xRegister');if(reg)reg.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(reg));if(!b.ministry_id)delete b.ministry_id;try{await post('/x/account',b);await xSaliyah()}catch(err){alert(err.message)}};
  const form=document.querySelector('#xCompose');if(form)form.onsubmit=async e=>{e.preventDefault();try{await post('/x/post',{body:new FormData(form).get('body')});await xSaliyah()}catch(err){alert(err.message)}};
  document.querySelectorAll('.xLike').forEach(b=>b.onclick=async()=>{try{await post('/x/like',{post_id:b.dataset.id});await xSaliyah()}catch(err){alert(err.message)}});
  document.querySelectorAll('.xReply').forEach(b=>b.onclick=async()=>{const body=prompt('اكتب ردك (500 حرف كحد أقصى)');if(!body)return;try{await post('/x/post',{body,reply_to:b.dataset.id});await xSaliyah()}catch(err){alert(err.message)}});
  document.querySelectorAll('.xRepost').forEach(b=>b.onclick=async()=>{try{await post('/x/post',{body:'إعادة نشر',repost_of:b.dataset.id});await xSaliyah()}catch(err){alert(err.message)}});
  document.querySelectorAll('.xFollow').forEach(b=>b.onclick=async()=>{try{const r=await post('/x/follow',{handle:b.dataset.handle});alert(r.following?'تمت المتابعة':'أُلغيت المتابعة')}catch(err){alert(err.message)}});
 }catch(err){page('إكس الصالية','<div class="notice">'+safe(err.message)+'</div>')}
}
